comms.text:
@1 וַהֲוָה כַּד שַׁלַח פַּרְעֹה יָת עַמָא וְלָא דַבָּרִינוּן יְיָ אֹרַח אַרְעָא פְלִשְׁתָּאֵי אֲרֵי קָרִיבָא הוּא אֲרֵי אֲמַר יְיָ דִילְמָא יְזוּעוּן עַמָא בְּמֶחֱזֵיהוֹן קְרָבָא וִיתוּבוּן לְמִצְרָיִם:
@2 וְאַסְחַר יְיָ יָת עַמָא אֹרַח מַדְבְּרָא יַמָא דְסוּף וּמְזָרְזִין סְלִיקוּ בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם:
@3 וְאַסִיק משֶׁה יָת גַרְמֵי יוֹסֵף עִמֵהּ אֲרֵי אוֹמָאָה אוֹמִי יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר מִדְכַּר דְכִיר יְיָ יָתְכוֹן וְתַסְקוּן יָת גַרְמַי מִכָּא עִמְכוֹן:
@4 וּנְטָלוּ מִסֻכּוֹת וּשְׁרוֹ בְאֵתָם בִּסְטַר מַדְבְּרָא:
@5 וַיְיָ מְדַבַּר קָדָמֵיהוֹן בִּימָמָא בְּעַמוּדָא דַעֲנָנָא לְדַבָּרוּתְהוֹן בְּאוֹרְחָא וְלֵילְיָא בְּעַמוּדָא דְאֶשָׁתָא לְאַנְהָרָא לְהוֹן לְמֵיזַל בִּימָמָא וּבְלֵילְיָא:
@6 לָא יַעֲדֵי עַמוּדָא דַעֲנָנָא בִּימָמָא וְאַף לָא עַמוּדָא דְאֶשָׁתָא בְּלֵילְיָא קֳדָם עַמָא:
@7 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@8 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וִיתוּבּוּן וְיִשְׁרוּן קֳדָם פּוּם חִירָתָא בֵּין מִגְדוֹל וּבֵין יַמָא קֳדָם בְּעֵיל צְפוֹן לְקִבְלֵהּ תִּשְׁרוּן עַל יַמָא:
@9 וְיֵימַר פַּרְעֹה עַל בְּנֵי יִשְׂרָאֵל מְעַרְבְּלִין אִנוּן בְּאַרְעָא אֲחַד עֲלֵיהוֹן מַדְבְּרָא:
@10 וְאַתְקֵף יָת לִבָּא דְפַרְעֹה וְיִרְדַף בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ וְיִדְעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ וַעֲבָדוּ כֵן:
@11 וְאִתְחַוָא לְמַלְכָּא דְמִצְרַיִם אֲרֵי אֲזַל עַמָא וְאִתְהֲפִיךְ לִבָּא דְפַרְעֹה וְעַבְדוֹהִי לְעַמָא וַאֲמָרוּ מָא דָא עֲבַדְנָא אֲרֵי שַׁלַחְנָא יָת יִשְׂרָאֵל מִפָּלְחָנָנָא:
@12 וְטַקִיס יָת רְתִכֵּהּ וְיָת עַמֵהּ דַבַּר עִמֵהּ:
@13 וּדְבַר שִׁתְּ מְאָה רְתִכִּין בְּחִירָן וְכֹל רְתִכֵּי מִצְרָאֵי וְגִבָּרִין מְמַנָן עַל כֻּלְהוֹן:
@14 וְתַקִיף יְיָ יָת לִבָּא דְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּרְדַף בָּתַר בְּנֵי יִשְׂרָאֵל וּבְנֵי יִשְׂרָאֵל נְפָקוּ בְּרֵישׁ גְלִי:
@15 וּרְדָפוּ מִצְרָאֵי בַּתְרֵיהוֹן וְאַדְבִּיקוּ יָתְהוֹן כַּד שָׁרָן עַל יַמָא כָּל סוּסָוַת רְתִכֵּי פַרְעֹה וּפָרָשׁוֹהִי וּמַשִׁרְיָתֵהּ עַל פּוּם חִירָתָא קֳדָם בְּעֵיל צְפוֹן:
@16 וּפַרְעֹה קְרֵיב וּזְקָפוּ בְנֵי יִשְׂרָאֵל יָת עֵינֵיהוֹן וְהָא מִצְרָאֵי נַטְלִין בַּתְרֵיהוֹן וּדְחִילוּ לַחֲדָא וּזְעִיקוּ בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@17 וַאֲמָרוּ לְמשֶׁה הֲמִדְלֵית קְבָרִין בְּמִצְרַיִם דְבַרְתָּנָא לִמְמַת בְּמַדְבְּרָא מָא דָא עֲבַדְתָּא לָנָא לְאַפָּקוּתָנָא מִמִצְרָיִם:
@18 הֲלָא דֵין פִּתְגָמָא דִי מַלֵלְנָא עִמָךְ בְמִצְרַיִם לְמֵימַר שְׁבוֹק מִנָנָא וְנִפְלַח יָת מִצְרָאֵי אֲרֵי טַב לָנָא דְנִפְלַח יָת מִצְרָאֵי מִדִנְמוּת בְּמַדְבְּרָא:
@19 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אִתְעַתָּדוּ וַחֲזוֹ יָת פּוּרְקָנָא דַיְיָ דְיַעְבֵּד לְכוֹן יוֹמָא דֵין אֲרֵי כְּמָא דִחֲזֵיתוּן יַת מִצְרָאֵי יוֹמָא דֵין לָא תוֹסְפוּן לְמֶחֱזֵיהוֹן עוֹד עַד עָלְמָא:
@20 יְיָ יְגִיחַ לְכוֹן קְרָב וְאַתּוּן תִּשְׁתְּקוּן:
@21 וַאֲמַר יְיָ לְמשֶׁה קַבֵּלִית צְלוֹתָךְ מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיִטְלוּן:
@22 וְאַתְּ טוֹל יָת חֻטְרָךְ וַאֲרֵים יָת יְדָךְ עַל יַמָא וּבְזָעוֹהִי וְיֵעֲלוּן בְּנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא:
@23 וַאֲנָא הָא אֲנָא מְתַקֵף יָת לִבָּא דְמִצְרָאֵי וְיֵעֲלוּן בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@24 וְיִדְּעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ בְּאִתְיַקָרוּתִי בְּפַרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@25 וּנְטַל מַלְאֲכָא דַיְיָ דִמְדַבַּר קֳדָם מַשְׁרִיתָא דְיִשְׂרָאֵל וַאֲתָא מִבַּתְרֵיהוֹן וּנְטַל עַמּוּדָא דַעֲנָנָא מִן קֳדָמֵיהוֹן וּשְׁרָא מִבַּתְרֵיהוֹן:
@26 וְעַל בֵּין מַשְׁרִיתָא דְמִצְרָאֵי וּבֵין מַשְׁרִיתָא דְיִשְׂרָאֵל וַהֲוָה עֲנָנָא וְקַבְלָא לְמִצְרָאֵי וּלְיִשְׂרָאֵל נְהַר כָּל לֵילְיָא וְלָא אִתְקְרִיבוּ דֵין לְוָת דֵין כָּל לֵילְיָא:
@27 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָּא וְדַבַּר יְיָ יָת יַמָּא בְּרוּחַ קִדוּמָא תַקִיף כָּל לֵילְיָא וְשַׁוִי יָת יַמָּא לְיַבֶּשְׁתָּא וְאִתְבְּזָעוּ מַיָּא:
@28 וְעַלוּ בְנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא וּמַיָּא לְהוֹן שׁוּרִין מִיַּמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@29 וּרְדָפוּ מִצְרָאֵי וְעַלוּ בַתְרֵיהוֹן כֹּל סוּסָוַת פַּרְעֹה רְתִכּוֹהִי וּפָרָשׁוֹהִי לְגוֹ יַמָא:
@30 וַהֲוָה בְּמַטְרַת צַפְרָא וְאִסְתְּכֵי יְיָ לְמַשְׁרִיתָא דְמִצְרָאֵי בְּעַמוּדָא דְאֶשָׁתָא וַעֲנָנָא וְשַׁגִישׁ יָת מַשְׁרִיתָא דְמִצְרָאֵי:
@31 וְאַעְדִי יָת גַלְגַלֵי רְתִכּוֹהִי וּמְדַבְּרִין לְהוֹן בִּתְקוֹף וַאֲמַר מִצְרָאֵי נֵעִירוֹק מִן קֳדָם יִשְׂרָאֵל אֲרֵי דָא הִיא גְבֻרְתָּא דַיְיָ דַעֲבֵד לְהוֹן קְרָבִין בְּמִצְרָיִם:
@32 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יָת יְדָךְ עַל יַמָא וִיתוּבוּן מַיָא עַל מִצְרָאֵי עַל רְתִכֵּיהוֹן וְעַל פָּרָשֵׁיהוֹן:
@33 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָא וְתָב יַמָא לְעִדַן צַפְרָא לְתָקְפֵּהּ וּמִצְרָאֵי עָרְקִין לְקַדָמוּתֵהּ וְשַׁנִיק יְיָ יָת מִצְרָאֵי בְּגוֹ יַמָא:
@34 וְתָבוּ מַיָא וַחֲפוֹ יָת רְתִכַּיָא וְיָת פָּרָשַׁיָא לְכֹל מַשִׁרְיַת פַּרְעֹה דְעַלוּ בַתְרֵיהוֹן בְּיַמָא לָא אִשְׁתָּאַר בְּהוֹן עַד חָד:
@35 וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא וּמַיָא לְהוֹן שׁוּרִין מִיַמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@36 וּפְרַק יְיָ בְּיוֹמָא הַהוּא יָת יִשְׂרָאֵל מִידָא דְמִצְרָאֵי וַחֲזוֹ יִשְׂרָאֵל יָת מִצְרָאֵי מַיְתִין עַל כֵּיף יַמָא:
@37 וַחֲזָא יִשְׂרָאֵל יָת גְבוּרְתָּא יְדָא רַבְּתָא דִי עֲבַד יְיָ בְּמִצְרַיִם וּדְחִילוּ עַמָא מִן קֳדָם יְיָ וְהֵמִינוּ בְּמֵימְרָא דַיְיָ וּבִנְבִיאוּת משֶׁה עַבְדֵהּ:
@38 בְּכֵן שַׁבַּח משֶׁה וּבְנֵי יִשְׂרָאֵל יָת תִּשְׁבַּחְתָּא הָדָא קֳדָם יְיָ וַאֲמָרוּ לְמֵימָר נְשַׁבַּח וְנוֹדֶה קָדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@39 תָּקְפִּי וְתִשְׁבַּחְתִּי דְחִילָא יְיָ וַאֲמַר בְּמֵימְרֵהּ וַהֲוָה לִי לְפָרָק דֵין אֱלָהַי וְאֶבְנֵי לֵהּ מַקְדְשָׁא אֱלָהָא דַאֲבָהָתַי וְאֶפְלַח קֳדָמוֹהִי:
@40 יְיָ מָרֵי נִצְחָן קְרָבַיָא יְיָ שְׁמֵהּ:
@41 רְתִכֵּי פַּרְעֹה וּמַשִׁרְיָתֵהּ שְׁדִי בְיַמָא וּשְׁפַר גִבָּרוֹהִי אִטְבָּעוּ בְּיַמָא דְסוּף:
@42 תְּהוֹמַיָא חֲפוֹ עֲלֵיהוֹן נְחָתוּ לְעוּמְקַיָא כְּאַבְנָא:
@43 יַמִינָךְ יְיָ אַדִיר בְּחֵילָא יַמִינָךְ יְיָ תְּבָּרַת סָנְאָה:
@44 וּבִסְגֵי תָקְפָּךְ תְּבַרְתָּנוּן לִדְקָמוּ עַל עַמָךְ שַׁלַחְתָּ רוּגְזָךְ שֵׁיצִנוּן כְּנוּרָא לְקַשָׁא:
@45 וּבְמֵימַר פּוּמָךְ חַכִּימוּ מַיָא קָמוּ כְשׁוּר אֲזָלַיָא קָפוּ תְהוֹמִין בְּלִבָּא דְיַמָא:
@46 דַהֲוָה אֲמַר סָנְאָה אֶרְדוֹף אַדְבֵּק אֲפַלֵג בִּזְתָא תִּשְׂבַּע מִנְהוֹן נַפְשִׁי אֶשְׁלוֹף חַרְבִּי תְּשֵׁיצִינוּן יְדִי:
@47 אֲמַרְתָּ בְּמֵימְרָךְ חֲפָא עֲלֵיהוֹן יַמָא אִשְׁתְּקָעוּ כַּאֲבָרָא בְּמַיִן תַּקִיפִין:
@48 לֵית בַּר מִנָךְ דְאַתְּ הוּא אֱלָהָא יְיָ לֵית בַּר מִנָךְ אֱלָהָא אַתְּ אַדִיר בְּקוּדְשָׁא דָחֵל תֻּשְׁבְּחָן עָבֵד פָּרִישָׁן:
@49 אֲרֵמְתָּ יַמִינָךְ בְּלַעְתְּנוּן אַרְעָא:
@50 דַבַּרְהִי בְטַבְוָתָךְ עַמָא דְנַן דִפְרָקְתָּ סוֹבַרְהִי בְתָקְפָּךְ לְדִירָא דְקֻדְשָׁךְ:
@51 שְׁמָעוּ עַמְמַיָא וְזָעוּ דַחֲלָא אַחֲדָתְנוּן דַהֲווֹ יָתְבִין בִּפְלָשֶׁת:
@52 בְּכֵן אִתְבְּהִילוּ רַבְרְבֵי אֱדוֹם תַּקִיפֵי מוֹאָב אֲחַדָתְנוּן רְתֵיתָא אִתְבָּרוּ כֹּל דַהֲווֹ יָתְבִין בִּכְנָעַן:
@53 תַּפִּיל עֲלֵיהוֹן אֵימְתָא וְדַחַלְתָּא בִּסְגֵי תָקְפָּךְ יִשְׁתְּקוּן כְּאַבְנָא עַד דְיֵעִבַּר עַמָךְ יְיָ יָת אַרְנוֹנָא עַד דְיֵעִבַּר עַמָא דְנַן דִי פְרַקְתָּא יָת יַרְדְנָא:
@54 תָּעֵלִנוּן וְתַשְׁרִינוּן בְּטוּרָא דְאַחְסַנְתָּךְ אֲתַר מְתַקֵן לְבֵית שְׁכִנְתָּךְ אַתְקֵנְתָּא יְיָ מַקְדְשָׁא יְיָ אַתְקְנוֹהִי יְדָיךְ:
@55 יְיָ מַלְכוּתֵהּ קָאֵם לְעָלַם וּלְעָלְמֵי עָלְמַיָא:
@56 אֲרֵי עַלוּ סוּסָוַת פַּרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי בְּיַמָא וַאֲתֵיב יְיָ עֲלֵיהוֹן יָת מֵי יַמָא וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא:
@57 וּנְסֵיבַת מִרְיָם נְבִיאֲתָא אֲחָתֵהּ דְאַהֲרֹן יָת תֻּפָּא בִּידַהּ וּנְפָקוּ כָל נְשַׁיָא בַּתְרָהָא בְּתֻפִּין וּבְחִנְגִין:
@58 וּמְעַנְיָא לְהוֹן מִרְיָם שַׁבָּחוּ וְאוֹדוּ קֳדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@59 וְאַטֵּל משֶׁה יָת יִשְׂרָאֵל מִיַמָא דְסוּף וּנְפָקוּ לְמַדְבְּרָא דְחַגְרָא וַאֲזָלוּ תְלָתָא יוֹמִין בְּמַדְבְּרָא וְלָא אַשְׁכָּחוּ מַיָא:
@60 וַאֲתוֹ לְמָרָה וְלָא יְכִילוּ לְמִשְׁתֵּי מַיָא מִמָרָה אֲרֵי מְרִירִין אִנוּן עַל כֵּן קְרָא שְׁמַהּ מָרָה:
@61 וְאִתְרָעָמוּ עַמָא עַל משֶׁה לְמֵימַר מָה נִשְׁתֵּי:
@62 וְצַלִי קֳדָם יְיָ וְאַלְפֵהּ יְיָ אָעָא וּרְמָא לְמַיָא וּבַסִימוּ מַיָא תַּמָן גְזַר לֵהּ קְיָם וְדִין וְתַמָן נַסְיֵהּ:
@63 וַאֲמַר אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וּדְכָשַׁר קֳדָמוֹהִי תַעְבֵּד וְתַצֵית לִפִקוּדוֹהִי וְתִטַר כָּל קְיָמוֹהִי כָּל מַרְעִין דִי שַׁוֵיתִי בְמִצְרַיִם לָא אֲשַׁוִנוּן עֲלָךְ אֲרֵי אֲנָא יְיָ אַסָךְ:
@64 וַאֲתוֹ לְאֵילִם וְתַמָן תְּרֵי עֲסַר מַבּוּעִין דְמַיִן וְשִׁבְעִין דִקְלִין וּשְׁרוֹ תַמָן עַל מַיָא:
@65 וּנְטָלוּ מֵאֵילִם וַאֲתוֹ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְּמַדְבְּרָא דְסִין דִי בֵין אֵילִם וּבֵין סִינָי בְּחַמְשַׁת עַסְרָא יוֹמָא לְיַרְחָא תִנְיָנָא לְמִפָּקְהוֹן מֵאַרְעָא דְמִצְרַיִם:
@66 וְאִתְרָעָמוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל עַל משֶׁה וְעַל אַהֲרֹן בְּמַדְבְּרָא:
@67 וַאֲמָרוּ לְהוֹן בְּנֵי יִשְׂרָאֵל לְוַי דְמִיתְנָא קֳדָם יְיָ בְּאַרְעָא דְמִצְרַיִם כַּד הֲוֵינָא יָתְבִין עַל דוּדֵי בִסְרָא כַּד הֲוֵינָא אָכְלִין לַחְמָא וְשָׂבְעִין אֲרֵי אַפֶּקְתּוּן יָתָנָא לְמַדְבְּרָא הָדֵין לְקַטָּלָא יָת כָּל קְהָלָא הָדֵין בְּכַפְנָא:
@68 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מָחֵית לְכוֹן לַחְמָא מִן שְׁמַיָא וְיִפְקוּן עַמָא וְיִלְקְטוּן פִּתְגַם יוֹם בְּיוֹמֵהּ בְּדִיל דַאֲנַסִנוּן הַיְהָכוּן בְּאוֹרַיְתִי אִם לָא:
@69 וִיהֵי בְּיוֹמָא שְׁתִיתָאָה וִיתַקְנוּן יָת דְיַיְתוּן וִיהֵי עַל חַד תְּרֵין עַל דְיִלְקְטוּן יוֹם יוֹם:
@70 וַאֲמַר משֶׁה וְאַהֲרֹן לְכָל בְּנֵי יִשְׂרָאֵל בְּרַמְשָׁא וְתִדְעוּן אֲרֵי יְיָ אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@71 וּבְצַפְרָא וְתֶחֱזוּן יָת יְקָרָא דַיְיָ כַּד שְׁמִיעַ (קֳדָמוֹהִי) יָת תֻּרְעֲמוּתְכוֹן עַל מֵימְרָא דַיְיָ וְנַחְנָא מָא אֲרֵי אַתְרַעַמְתּוּן עֲלָנָא:
@72 וַאֲמַר משֶׁה בִּדְיִתֵּן יְיָ לְכוֹן בְּרַמְשָׁא בִּסְרָא לְמֵיכַל וְלַחְמָא בְּצַפְרָא לְמִסְבַּע בְּדִשְׁמִיעַן קֳדָם יְיָ יָת תֻּרְעֲמוּתְכוֹן דִי אַתּוּן מִתְרַעֲמִין עֲלוֹהִי וְנַחְנָא מָא לָא עֲלָנָא תֻּרְעֲמוּתְכוֹן אֶלָהֵן עַל מֵימְרָא דַיְיָ:
@73 וַאֲמַר משֶׁה לְאַהֲרֹן אֱמַר לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל קְרִיבוּ קֳדָם יְיָ אֲרֵי שְׁמִיעַן קֳדָמוֹהִי יָת תֻּרְעֲמוּתְכוֹן:
@74 וַהֲוָה כַּד מַלִיל אַהֲרֹן עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵלּ וְאִתְפְּנִיוּ לְמַדְבְּרָא וְהָא יְקָרָא דַיְיָ אִתְגְלִי בַּעֲנָנָא:
@75 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@76 שְׁמִיעַ קֳדָמַי יָת תֻּרְעֲמַת בְּנֵי יִשְּׂרָאֵל מַלֵיל עִמְהוֹן לְמֵימַר בֵּין שִׁמְשַׁיָא תֵּיכְלּוּן בִּסְרָא וּבְצַפְרָא תִּשְׂבְּעוּן לַחְמָא וְתִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@77 וַהֲוָה בְרַמְשָׁא וּסְלֵיקַת סְלָיו וַחֲפַת יָת מַשְׁרִיתָא וּבְצַפְרָא הֲוַת נְחָתַת טַלָא סְחוֹר סְחוֹר לְמַשְׁרִיתָא:
@78 וּסְלֵיקַת נְחָתַת טַלָא וְהָא עַל אַפֵּי מַדְבְּרָא דַעְדַק מְקַלַף דַעְדַק כְּגִיר כִּגְלִידָא עַל אַרְעָא:
@79 וַחֲזוֹ בְנֵי יִשְׂרָאֵל וַאֲמָרוּ גְבַר לַאֲחוּהִי מַנָא הוּא אֲרֵי לָא יְדָעוּ מָא הוּא וַאֲמַר משֶׁה לְהוֹן הוּא לַחְמָא דִי יְהַב יְיָ לְכוֹן לְמֵיכַל:
@80 דֵין פִּתְגָמָא דִי פַקֵיד יְיָ לְקוּטוּ מִנֵהּ גְבַר לְפוּם מֵיכְלֵהּ עֻמְרָא לְגֻלְגַלְתָּא מִנְיַן נַפְשָׁתֵיכוֹן גְבַר לְדִי בְמַשְׁכְּנֵהּ תִּסְבוּן:
@81 וַעַבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וּלְקָטוּ דְאַסְגֵי וּדְאַזְעֵר:
@82 וּכְלוֹ בְעוּמְרָא וְלָא אוֹתַר דְאַסְגֵי וּדְאַזְעֵר לָא חַסִיר גְבַר לְפוּם מֵיכְלֵהּ לְקָטוּ:
@83 וַאֲמַר משֶׁה לְהוֹן אֱנַשׁ לָא יַשְׁאַר מִנֵהּ עַד צַפְרָא:
@84 וְלָא קַבִּילוּ מִן משֶׁה וְאַשְׁאָרוּ גֻבְרַיָא מִנֵה עַד צַפְרָא וּרְחֵשׁ רִיחֲשָׁא וּסְרִי וּרְגַז עֲלֵיהוֹן משֶׁה:
@85 וּלְקָטוּ יָתֵהּ בִּצְפַר בִּצְפָר גְבַר לְפוּם מֵיכְלֵהּ וּמָא דְמִשְׁתָּאַר מִנֵהּ עַל אַפֵּי חַקְלָא כַּד חֲמָא עֲלוֹהִי שִׁמְשָׁא פָּשָׁר:
@86 וַהֲוָה בְּיוֹמָא שְׁתִיתָאָה לְקָטוּ לַחְמָא עַל חַד תְּרֵין תְּרֵין עֻמְרִין לְחָד וַאֲתוֹ כָּל רַבְרְבֵי כְנִשְׁתָּא וְחַוִיאוּ לְמשֶׁה:
@87 וַאֲמַר לְהוֹן הוּא דִי מַלִיל יְיָ שְׁבָתָא שְׁבַת קוּדְשָׁא קֳדָם יְיָ מְחָר יָת דִי אַתּוּן עֲתִידִין לְמֵפָא אֲפוֹ וְיָת דִי אַתּוּן עֲתִידִין לְבַשָׁלָא בַּשִׁילוּ וְיָת כָּל מוֹתָרָא אַצְנָעוּ לְכוֹן לְמַטְּרַת עַד צַפְרָא:
@88 וְאַצְנָעוּ יָתֵהּ עַד צַפְרָא כְּמָא דְפַקִיד משֶׁה וְלָא סְרִי וְרִיחֲשָׁא לָא הֲוָה בֵהּ:
@89 וַאֲמַר משֶׁה אִכְלוּהִי יוֹמָא דֵין אֲרֵי שַׁבְּתָא יוֹמָא דֵין קֳדָם יְיָ יוֹמָא דֵין לָא תַשְׁכְּחֻנֵהּ בְּחַקְלָא:
@90 שִׁתָּא יוֹמִין תִּלְקְטֻנֵהּ וּבְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא לָא יְהֵי בֵהּ:
@91 וַהֲוָה בְּיוֹמָא שְׁבִיעָאָה נְפָקוּ מִן עַמָא לְמִלְקָטּ וְלָא אַשְׁכָּחוּ:
@92 וַאֲמַר יְיָ לְמשֶׁה עַד אֵימָתַי אַתּוּן מְסָרְבִין לְמִטַר פִּקוּדַי וְאוֹרָיָתַי:
@93 חֲזוֹ אֲרֵי יְיָ יְהַב לְכוֹן שַׁבְּתָא עַל כֵּן הוּא יָהֵב לְכוֹן בְּיוֹמָא שְׁתִיתָאָה לְחֵם תְּרֵין יוֹמִין תִּיבוּ אֲנַשׁ תְּחוֹתוֹהִי לָא יִפּוֹק אֲנַשׁ מֵאַתְרֵהּ בְּיוֹמָא שְׁבִיעָאָה:
@94 וְנָחוּ עַמָא בְּיוֹמָא שְׁבִיעָאָה:
@95 וּקְרוֹ בֵית יִשְׂרָאֵל יָת שְׁמֵהּ מָן וְהוּא כְּבַר זְרַע גִדָא חִוָר וְטַעְמֵה כְּאִסְקְרֵיטָוָן בִּדְבָשׁ:
@96 וַאֲמַר משֶׁה דֵין פִּתְגָמָא דִי פַקִיד יְיָ מִלֵי עֻמְרָא מִנֵהּ לְמַטְרָא לְדָרֵיכוֹן בְּדִיל דְיֶחְזוּן יָת לַחְמָא דִי אוֹכָלִית יָתְכוֹן בְּמַדְבְּרָא בְּאַפָּקוּתִי יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@97 וַאֲמַר משֶׁה לְאַהֲרֹן סַב צְלוֹחִית חֲדָא וְהַב תַמָן מְלֵי עֻמְרָא מָן וְאַצְנַע יָתֵהּ קֳדָם יְיָ לְמַטְרָא לְדָרֵיכוֹן:
@98 כְּמָא דִי פַקִיד יְיָ לְמשֶׁה וְאַצְנְעֵהּ אַהֲרֹן קֳדָם סַהֲדוּתָא לְמַטְרָא:
@99 וּבְנֵי יִשְׂרָאֵל אֲכָלוּ יָת מַנָא אַרְבְּעִין שְׁנִין עַד דְמֵיתֵיהוֹן לְאַרְעָא יָתְבָתָא יָת מַנָא אֲכָלוּ עַד דְאָתוֹ לִסְיָפֵי אַרְעָא דִכְנָעַן:
@100 וְעֻמְרָא חַד מִן עַסְרָא בִּתְלָת סְאִין הוּא:
@101 וּנְטָלוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִמַדְבְּרָא דְסִין לְמַטְלָנֵיהוֹן עַל מֵימְרָא דַיְיָ וּשְׁרוֹ בִּרְפִידִים וְלֵית מַיָא לְמִשְׁתֵּי עַמָא:
@102 וּנְצָא עַמָא עִם משֶׁה וַאֲמָרוּ הָבוּ לָנָא מַיָא וְנִשְׁתֵּי וַאֲמַר לְהוֹן משֶׁה מָא אַתּוּן נָצָן עִמִי מָא מְנַסוּן אַתּוּן קֳדָם יְיָ:
@103 וּצְחִי תַמָן עַמָא לְמַיָא וְאִתְרַעַם עַמָא עַל משֶׁה וַאֲמַר לְמָא דְנַן אַסֶקְתָּנָא מִמִצְרַיִם לְקַטָלָא יָתִי וְיָת בָּנַי וְיָת בְּעִירַי בְּצָחוּתָא:
@104 וְצַלִי משֶׁה קֳדָם יְיָ לְמֵימַר מָא אֶעְבֵּד לְעַמָא הָדֵין עוֹד זְעֵיר פּוֹן וְיִרְגְמֻנִי:
@105 וַאֲמַר יְיָ לְמשֶׁה עִבַּר קֳדָם עַמָא וּדְבַר עִמָךְ מִסָבֵי יִשְׂרָאֵל וְחֻטְרָךְ דִי מָחֵיתָא בֵהּ יָת נַהֲרָא סַב בִּידָךְ וְתֵיזִל:
@106 הָא אֲנָא קָאֵם קֳדָמָךְ תַּמָן עַל טִנָרָא בְּחוֹרֵב וְתִמְחֵי בְטִנָרָא וְיִפְּקוּן מִנֵהּ מַיָא וְיִשְׁתֵּי עַמָא וַעֲבַד כֵּן משֶׁה לְעֵינֵי סָבֵי יִשְׂרָאֵל:
@107 וּקְרָא שְׁמָא דְאַתְרָא נִסֵיתָא וּמַצוּתָא עַל דִנְצוֹ בְּנֵי יִשְׂרָאֵל וְעַל דְנַסִיאוּ קֳדָם יְיָ לְמֵימַר הֲאִית שְׁכִינְתָּא דַיְיָ בֵּינָנָא אִם לָא:
@108 וַאֲתָא עֲמָלֵק וַאֲגַח קְרָבָא עִם יִשְׂרָאֵל בִּרְפִידִם:
@109 וַאֲמַר משֶׁה לִיהוֹשֻׁעַ בְּחַר לָנָא גֻבְרַיָא וּפוּק אֲגַח קְרָבָא בַּעֲמָלֵק מְחָר אֲנָא קָאֵם עַל רֵישׁ רָמָתָא וְחוּטְרָא דְאִתְעֲבִידוּ בֵהּ נִסִין מִן קֳדָם יְיָ בִּידִי:
@110 וַעֲבַד יְהוֹשֻׁעַ כְּמָא דְאֲמַר לֵהּ משֶׁה לְאַגָחָא קְרָבָא בַּעֲמָלֵק וּמשֶׁה אַהֲרֹן וְחוּר סְלִיקוּ לְרֵישׁ רָמָתָא:
@111 וַהֲוִי כַּד יְרִים משֶׁה יְדוֹהִי וּמִתְגַבְּרִין דְבֵית יִשְׂרָאֵל וְכַד מַנַח יְדוֹהִי וּמִתְגַבְּרִין דְבֵית עֲמָלֵק:
@112 וִידֵי משֶׁה יְקָרָן וּנְסִיבוּ אַבְנָא וְשַׁוִיאוּ תְחוֹתוֹהִי וִיתֵב עֲלַהּ וְאַהֲרֹן וְחוּר סַעְדָן בִּידוֹהִי מִכָּא חַד וּמִכָּא חַד וַהֲוָה יְדוֹהִי פְּרִיסָן בִּצְלוֹ עַד דְעַל שִׁמְשָׁא:
@113 וְתַבַּר יְהוֹשֻׁעַ יָת עֲמָלֵק וְיָת עַמֵהּ לְפִתְגָם דְחָרֶב:
@114 וַאֲמַר יְיָ לְמשֶׁה כְּתָב דָא דוּכְרָנָא בְּסִפְרָא וְשַׁוִי קֳדָם יְהוֹשֻׁעַ אֲרֵי מִמְחָא אֶמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא:
@115 וּבְנָא משֶׁה מַדְבְּחָא וּפְלַח עֲלוֹהִי קֳדָם יְיָ דַעֲבַד לֵהּ נִסִין:
@116 וַאֲמַר בִּשְׁבוּעָה אֲמִירָא דָא מִן קֳדָם דְחֵילָא דִשְׁכִנְתֵּהּ עַל כָּרְסֵהּ יְקָרֵהּ דְעָתִיד דְאִתָּגַח קְרָבָא קֳדָם יְיָ בִּדְבֵית עֲמָּלֵק לְשֵׁצָיוּתְהוֹן מִדָרֵי עָלְמָא: פפפ:

@1 **ויהי בשלח פרעה** וגו' **ולא נחם.** ולא נהגם, כמו (שמות לב לד) לך נחה את העם, (משלי ו כב) בהתהלכך תנחה אותך: **כי קרוב הוא.** ונוח לשוב באותו הדרך למצרים. ומדרשי אגדה יש הרבה: **בראתם מלחמה.** כגון מלחמת (במדבר יד מה) וירד העמלקי והכנעני וגו' . אם הלכו דרך ישר היו חוזרים, ומה אם כשהקיפם דרך מעקם אמרו (במדבר יד ד) נתנה ראש ונשובה מצרימה, אם הוליכם בפשוטה על אחת כמה וכמה: **פן ינחם.** יחשבו מחשבה על שיצאו ויתנו לב לשוב:
@2 **ויסב.** הסבם מן הדרך הפשוטה לדרך העקומה: **ים סוף.** כמו לים סוף. וסוף הוא לשון אגם שגדלים בו קנים, כמו (שמות ב ג) ותשם בסוף, (ישעיה יט ו) קנה וסוף קמלו: **וחמשים.** אין חמושים אלא מזינים. לפי שהסבן במדבר גרם להם שעלו חמושים, שאלו הסיבן דרך ישוב לא היו מחמשים להם כל מה שצריכין, אלא כאדם שעובר ממקום למקום ובדעתו לקנות שם מה שיצטרך, אבל כשהוא פורש למדבר צריך לזמן לו כל הצרך, ומקרא זה לא נכתב כי אם לשבר את האזן, שלא תתמה במלחמת עמלק ובמלחמות סיחון ועוג ומדין, מהיכן היו להם כלי זין שהכום ישראל בחרב. וכן הוא אומר (יהושע א יד) ואתם תעברו חמשים. וכן תרגם אנקלוס מזרזין, כמו וירק את חניכיו (בראשית יד יד) וזריז. דבר אחר חמושים אחד מחמשה יצאו, וארבעה חלקים מתו בשלשת ימי אפלה:
@3 **השבע השביע.** השביעם שישביעו לבניהם. ולמה לא השביע את בניו שישאוהו לארץ כנען מיד, כמו שהשביעו יעקב, אמר יוסף אני שליט הייתי במצרים והיה ספק בידי לעשות, אבל בני לא יניחום מצרים לעשות, לכך השביעם לכשיגאלו ויצאו משם שישאוהו: **והעליתם את עצמתי מזה אתכם.** לאחיו השביע כן, למדנו שאף עצמות כל השבטים העלו עמהם, שנאמר אתכם:
@4 **ויסעו מסכת.** ביום השני, שהרי בראשון באו מרעמסס לסכות:
@5 **לנחתם הדרך.** נקוד פת''ח, שהוא כמו להנחותם, כמו (דברים א לג) לראותכם בדרך אשר תלכו בה, שהוא כמו להראותכם, אף כאן להנחותם על ידי שליח. ומי הוא השליח עמוד הענן, והקדוש ברוך הוא בכבודו מוליכו לפניהם. ומכל מקום את עמוד הענן הכין להנחותם על ידו, שהרי על ידי עמוד הענן הם הולכים, ועמוד הענן אינו לאורה אלא להורותם הדרך:
@6 **לא ימיש.** הקדוש ברוך הוא את עמוד הענן יומם ועמוד האש לילה. מגיד שעמוד הענן משלים לעמוד האש ועמוד האש משלים לעמוד הענן, שעד שלא ישקע זה עולה זה:
@8 **וישבו.** לאחוריהם לצד מצרים היו מקרבין כל יום השלישי כדי להטעות את פרעה שיאמר תועים הם בדרך, כמו שנאמר (פסוק ג) ואמר פרעה לבני ישראל וגו' : **ויחנו לפני פי החירת.** הוא פיתום, ועכשיו נקרא פי החירות על שם שנעשו בני חורין, והם שני סלעים גבוהים וזקופים, והגיא שביניהם קרוי פי הסלעים: **לפני בעל צפן.** הוא נשאר מכל אלהי מצרים, כדי להטעותן, שיאמרו קשה יראתן. ועליו פרש איוב (איוב יב כג) משגיא לגוים ויאבדם:
@9 **ואמר פרעה.** כשישמע שהם שבים לאחוריהם: **לבני ישראל.** על בני ישראל. וכן (פסוק יד) ה' ילחם לכם. עליכם, (בראשית כ יג) אמרי לי אחי הוא. אמרי עלי: **נבכים הם.** כלואים ומשקעים ובלעז שירי''ץ , כמו (תהלים פד ז) בעמק הבכא, (איוב כח יא) מבכי נהרות, (שם לח טז) נבכי ים. נבכים הם כלואים הם במדבר, שאינן יודעין לצאת ממנו ולהיכן ילכו:
@10 **ואכבדה בפרעה.** כשהקדוש ברוך הוא מתנקם ברשעים שמו מתגדל ומתכבד. וכן הוא אומר (יחזקאל לח כב) ונשפטתי אתו וגו' , ואחר כך (שם כג) והתגדלתי והתקדשתי ונודעתי וגו' , ואומר (תהלים עו ד) שמה שבר רשפי קשת, ואחר כך (שם פסוק ב) נודע ביהודה אלהים, ואומר (שם ט יז) נודע ה' משפט עשה: **בפרעה ובכל חילו.** הוא התחיל בעברה וממנו התחילה הפרענות: **ויעשו כן.** להגיד שבחן ששמעו לקול משה, ולא אמרו היאך נתקרב אל רודפינו, אנו צריכים לברוח, אלא אמרו אין לנו אלא דברי בן עמרם:
@11 **ויגד למלך מצרים.** איקטורין שלח עמהם, וכיון שהגיעו לשלשת ימים שקבעו לילך ולשוב וראו שאינן חוזרין למצרים, באו והגידו לפרעה ביום הרביעי. בחמישי ובששי רדפו אחריהם, וליל שביעי ירדו לים, בשחרית אמרו שירה, והוא יום שביעי של פסח, לכן אנו קורין השירה ביום השביעי: **ויהפך.** נהפך ממה שהיה, שהרי אמר להם (שמות יב לא) קומו צאו מתוך עמי, ונהפך לבב עבדיו, שהרי לשעבר היו אומרים לו (שם י ז) עד מתי יהיה זה לנו למוקש, ועכשיו נהפכו לרדוף אחריהם בשביל ממונם שהשאילום: **מעבדנו.** מעבוד אותנו:
@12 **ויאסר את רכבו.** הוא בעצמו: **ואת עמו לקח עמו.** משכם בדברים לקינו ונטלו ממוננו ושלחנום, בואו עמי ואני לא אתנהג עמכם כשאר מלכים, דרך שאר מלכים עבדיו קודמין לו במלחמה, ואני אקדים לפניכם, שנאמר (פסוק י) ופרעה הקריב, הקריב עצמו ומהר לפני חילותיו. דרך שאר מלכים לטול בזה בראש כמו שיבחר, אני אשוה עמכם בחלק, שנאמר (שמות טו ט) אחלק שלל:
@13 **בחור.** נבחרים, בחור לשון יחיד כל רכב ורכב שבמנין זה היה בחור: **וכל רכב מצרים.** ועמהם כל שאר הרכב ומהיכן היו הבהמות הללו, אם תאמר משל מצרים, הרי נאמר (שמות ט ו) וימת כל מקנה מצרים, ואם תאמר משל ישראל, והלא נאמר (שם י כו) וגם מקננו ילך עמנו. משל מי היו, מן הירא את דבר ה' (שם ט כ) . מכאן היה רבי שמעון אומר כשר שבמצרים הרוג, טוב שבנחשים רצוץ את מוחו: **ושלשם על כלו.** שרי צבאות כתרגומו:
@14 **ויחזק ה' את לב פרעה.** שהיה תולה אם לרדוף אם לאו. וחזק את לבו לרדוף: **ביד רמה.** גבורה גבוהה ומפרסמת:
@16 **ופרעה הקריב.** היה לו לכתוב ופרעה קרב, מהו הקריב, הקריב עצמו ונתאמץ לקדם לפניהם, כמו שהתנה עמהם: **נסע אחריהם.** בלב אחד כאיש אחד. דבר אחר והנה מצרים נוסע אחריהם, ראו שר של מצרים נוסע מן השמים לעזור למצרים. תנחומא: **ויצעקו.** תפשו אמנות אבותם. באברהם הוא אומר (בראשית יט כז) אל המקום אשר עמד שם, ביצחק (שם כד סג) לשוח בשדה, ביעקב (שם כח יא) ויפגע במקום:
@17 **המבלי אין קברים.** וכי מחמת חסרון קברים שאין קברים במצרים לקבר שם לקחתנו משם. ש''י פו''ר פיילנצ''א ד''י נו''ן פושי''ש בלעז :
@18 **אשר דברנו אליך במצרים.** והיכן דברו, (שמות ה כא) ירא ה' עליכם וישפוט: **ממתנו.** מאשר נמות, ואם היה נקוד מלאפו''ם היה נבאר ממיתתנו, עכשיו שנקוד בשור''ק נבאר מאשר נמות, וכן (להלן טז ג) מי יתן מותנו. שנמות, וכן (שמואל ב' יט א) מי יתן מותי, דאבשלום. שאמות, כמו (צפניה ג ח) ליום קומי לעד, (דברי הימים ב' יח כו) עד שובי בשלום, שאקום שאשוב:
@19 **כי אשר ראיתם את מצרים** וגו' **.** מה שראיתם אותם אינו אלא היום, היום הוא שראיתם אותם ולא תוסיפו עוד:
@20 **ה' ילחם לכם.** בשבילכם. וכן (פסוק כה) כי ה' נלחם להם, וכן (איוב יג ח) אם לאל תריבון, וכן (בראשית כד ז) ואשר דבר לי וכן (שופטים ו לא) האתם תריבון לבעל:
@21 **מה תצעק אלי.** למדנו שהיה משה עומד ומתפלל, אמר לו הקדוש ברוך הוא לא עת עתה להאריך בתפלה שישראל נתונין בצרה. דבר אחר מה תצעק אלי עלי הדבר תלוי ולא עליך, כמו שנאמר להלן (ישעיה מה יא) על בני ועל פעל ידי תצוני: **דבר אל בני ישראל ויסעו.** אין להם אלא לסע שאין הים עומד בפניהם, כדאי זכות אבותיהם והם והאמונה שהאמינו בי ויצאו, לקרוע להם הים:
@25 **וילך מאחריהם.** להבדיל בין מחנה מצרים ובין מחנה ישראל, ולקבל חצים ובליסטראות של מצרים. בכל מקום הוא אומר מלאך ה', וכאן מלאך האלהים, אין אלהים בכל מקום אלא דין, מלמד שהיו ישראל נתונין בדין באותה שעה אם להנצל אם להאבד עם מצרים: **ויסע עמוד הענן.** כשחשכה והשלים עמוד הענן את המחנה לעמוד האש, לא נסתלק הענן כמו שהיה רגיל להסתלק ערבית לגמרי, אלא נסע והלך לו מאחריהם להחשיך למצרים:
@26 **ויבא בין מחנה מצרים.** משל למהלך בדרך ובנו מהלך לפניו. באו לסטים לשבותו, נטלו מלפניו ונתנו לאחריו, באו זאבים מאחריו, נתנו לפניו, באו לסטים לפניו וזאבים מאחריו, נתנו על זרועו ונלחם בהם, כך (הושע יא ג) ואנכי תרגלתי לאפרים קחם על זרועותיו: **ויהי הענן והחשך.** למצרים: **ויאר.** עמוד האש את הלילה לישראל, והולך לפניהם כדרכו ללכת כל הלילה, והחשך של ערפל לצד מצרים: **ולא קרב זה אל זה.** מחנה אל מחנה:
@27 **ברוח קדים עזה.** ברוח קדים שהיא עזה שברוחות, היא הרוח שהקדוש ברוך הוא נפרע בה מן הרשעים, שנאמר (ירמיה יח יז) ברוח קדים אפיצם, (הושע יג טו) יבא קדים רוח ה', (יחזקאל כז כו) רוח הקדים שברך בלב ימים, (ישעיה כז ח) הגה ברוחו הקשה ביום קדים: **ויבקעו המים.** כל מים שבעולם:
@29 **כל סוס פרעה.** וכי סוס אחד היה אלא מגיד שאין כלם חשובין לפני המקום אלא כסוס אחד:
@30 **באשמרת הבקר.** שלשת חלקי הלילה קרויין אשמורות, ואותה שלפני הבקר קורא אשמורת הבקר. ואומר אני לפי שהלילה חלוק למשמרות שיר של מלאכי השרת, כת אחר כת לשלשה חלקים, לכך קרוי אשמורת, וזהו שתרגם אנקלוס במטרת: **וישקף.** ויבט, כלומר פנה אליהם להשחיתם, ותרגומו ואסתכי, אף הוא לשון הבטה, כמו (במדבר כג יד) שדה צופים. חקל סכותא: **בעמוד אש וענן.** עמוד ענן יורד ועושה אותו כטיט ועמוד אש מרתיחו, וטלפי סוסיהם משתמטות: **ויהם.** לשון מהומה, אישטורדישו''ן בלעז ערבבם, נטל סגניות שלהם. ושנינו בפרקי רבי אליעזר בנו של רבי יוסי הגלילי כל מקום שנאמר בו מהומה, הרעמת קול הוא, וזה אב לכלן (שמואל א' ז י) וירעם ה' בקול גדול וגו' על פלשתים ויהמם:
@31 **ויסר את אפן מרכבתיו.** מכח האש נשרפו הגלגלים והמרכבות נגררות, והיושבים בהם נעים ואיבריהן מתפרקין: **וינהגהו בכבדת.** בהנהגה שהיא כבדה וקשה להם, במדה שמדדו (שמות ט לד) ויכבד לבו הוא ועבדיו, אף כאן וינהגהו בכבדות: **נלחם להם במצרים.** במצרים. דבר אחר במצרים, בארץ מצרים, שכשם שאלו לוקים על הים, כך לוקים אותם שנשארו במצרים:
@32 **וישבו המים.** שזקופים ועומדים כחומה, ישובו למקומם ויכסו על מצרים:
@33 **לפנות בקר.** לעת שהבקר פונה לבא: **לאיתנו.** לתקפו הראשון: **נסים לקראתו.** שהיו מהממים ומטרפים ורצין לקראת המים: **וינער ה'.** כאדם שמנער את הקדרה והופך העליון למטה והתחתון למעלה, כך היו עולין ויורדין ומשתברין בים, ונתן הקדוש ברוך הוא בהם חיות לקבל היסורין: **וינער.** ושניק, והוא לשון טרוף בלשון ארמי והרבה יש במדרשי אגדה:
@34 **ויכסו את הרכב** וגו' **לכל חיל פרעה.** כך דרך המקראות לכתוב למ''ד יתרה, כמו (להלן כג) לכל כליו תעשה נחשת, וכן (שם יט) לכל כלי המשכן בכל עבודתו, (במדבר ד לב) ויתדותם ומיתריהם לכל כליהם, ואינה אלא תקון לשון:
@36 **וירא ישראל את מצרים מת.** שפלטן הים על שפתו, כדי שלא יאמרו ישראל כשם שאנו עולים מצד זה כך הם עולין מצד אחר רחוק ממנו וירדפו אחרינו:
@37 **את היד הגדלה.** את הגבורה הגדולה שעשתה ידו של הקדוש ברוך הוא. והרבה לשונות נופלין על לשון יד, וכלן לשון יד ממש הן, והמפרשו יתקן הלשון אחר ענין הדבור:
@38 **אז ישיר משה.** אז כשראה הנס עלה בלבו שישיר שירה, וכן (יהושע י יב) אז ידבר יהושע, וכן (מלכים א' ז ח) ובית יעשה לבת פרעה, חשב בלבו שיעשה לה, אף כאן ישיר, אמר לו לבו שישיר, וכן עשה, ויאמרו לאמר אשירה לה'. וכן ביהושע, כשראה הנס אמר לו לבו שידבר וכן עשה (יהושע י יב) ויאמר לעיני ישראל, וכן שירת הבאר שפתח בה (במדבר כא יז) אז ישיר ישראל, פרש אחריו עלי באר ענו לה. (מלכים יא ז) אז יבנה שלמה במה, פרשו בו חכמי ישראל שבקש לבנות ולא בנה. למדנו שהיו''ד על שם המחשבה נאמרה, זהו לישב פשוטו. אבל מדרשו אמרו רבותינו זכרונם לברכה, מכאן רמז לתחית המתים מן התורה, וכן בכלן חוץ משל שלמה, שפרשוהו, בקש לבנות ולא בנה. ואין לומר ולישב הלשון הזה כשאר דברים הנכתבים בלשון עתיד והן מיד, כגון (איוב א ה) ככה יעשה איוב, (במדבר ט כג) על פי ה' יחנו, (שם כ) ויש אשר יהיה הענן, לפי שהן דבר ההוה תמיד, ונופל בו בין לשון עתיד בין לשון עבר, אבל זה שלא היה אלא לשעה אינו יכול לישבו בלשון הזה: **כי גאה גאה.** שנתגאה על כל גאה כתרגומו. דבר אחר בא הכפל לומר שעשה דבר שאי אפשר לבשר ודם לעשות, כשהוא נלחם בחבירו ומתגבר עליו מפילו מן הסוס וכאן סוס ורוכבו רמה בים וכל שאי אפשר לעשות על ידי זולתו נופל בו לשון גאות, כמו (ישעיה יב ה) כי גאות עשה, וכן כל השירה תמצא כפולה (פסוק ב) עזי וזמרת יה ויהי לי לישועה (פסוק ג) ה' איש מלחמה ה' שמו, וכן כלם. דבר אחר כי גאה גאה על כל השירות, וכל מה שאקלס בו עוד יש בו תוספת, ולא כמדת מלך בשר ודם שמקלסין אותו ואין בו: **סוס ורכבו.** שניהם קשורין זה בזה והמים מעלין אותם לרום ומורידין אותם לעמק ואינן נפרדין: **רמה.** השליך וכן (דניאל ג ו) יתרמא לגוא אתון נורא. ומדרש אגדה כתוב אחד אומר רמה, וכתוב אחד אומר (פסוק ד) ירה, מלמד שהיו עולין לרום ויורדין לתהום, כמו (איוב לח ו) מי ירה אבן פנתה, מלמעלה למטה:
@39 **עזי וזמרת יה.** אונקלוס תרגם תוקפי ותושבחתי. עזי כמו עזי בשור''ק, וזמרת כמו וזמרתי. ואני תמה על לשון המקרא שאין לך כמוהו בנקדתו במקרא אלא בשלשה מקומות שהוא סמוך אצל וזמרת, וכל שאר מקומות נקוד שור''ק, (ירמיה טז יט) ה' עזי ומעזי, (תהלים נט י) עזו אליך אשמרה. וכן כל תבה בת שתי אותיות הנקודה מלאפו''ם כשהיא מארכת באות שלישית ואין השניה בשו''א בחטף, הראשונה נקודה בשור''ק כגון עז עזי, רק רקי, חק חקי, על עלו, יסור עלו (ישעיה י כז) , כל כלו ושלישים על כלו (לעיל יד ז) . ואלו שלושה עזי וזמרת של כאן, ושל ישעיה (ישעיה יב ב) ושל תהלים (תהלים קיח יד) נקודים בחטף קמ''ץ, ועוד אין באחד מהם כתוב וזמרתי אלא וזמרת, וכלם סמוך להם ויהי לי לישועה, לכך אני אומר לישב לשון המקרא, שאין עזי כמו עזי, ולא וזמרת כמו וזמרתי, אלא עזי שם דבר הוא, כמו (שם קכג א) היושבי בשמים, (עובדיה א ג) שוכני בחגוי סלע, (דברים לג טז) שוכני סנה. וזהו השבח עזי וזמרת יה הוא היה לי לישועה, וזמרת דבוק הוא לתיבת ה', כמו (שופטים ה כג) לעזרת ה', (ישעיה ט יח) בעברת ה', (קהלת ג יח) על דברת בני האדם. ולשון וזמרת לשון (ויקרא כה ד) לא תזמר, (ישעיה כה ה) זמיר עריצים, לשון כסוח וכריתה. עזו ונקמתו של אלהינו היה לנו לישועה. ואל תתמה על לשון ויהי שלא נאמר היה, שיש לנו כמה מקראות מדברים בלשון זה, וזה דגמתו (מלכים א ו ה) את קירות הבית סביב להיכל ולדביר ויעש צלעות סביב, היה לו לומר עשה צלעות סביב, וכן בדברי הימים (דברי הימים ב' י יז) ובני ישראל היושבים בערי יהודה וימלך עליהם רחבעם, היה לו לומר מלך עליהם רחבעם, (במד' יד טז) מבלתי יכולת ה' וגו' וישחטם, היה לו לומר שחטם, (שם לו. לז) והאנשים אשר שלח משה וגו' וימתו, מתו היה לו לומר, (שמות ט כא) ואשר לא שם לבו אל דבר ה' ויעזב, היה לו לומר עזב: **זה אלי.** בכבודו נגלה עליהם והיו מראין אותו באצבע, ראתה שפחה על הים מה שלא ראו נביאים: **ואנוהו.** אנקלוס תרגם לשון נוה, (ישעיה לג כ) נוה שאנן, (שם סה י) לנוה צאן. דבר אחר ואנוהו לשון נוי, אספר נויו ושבחו לבאי עולם, כגון (שיר השירים ה ט. י) מה דודך מדוד דודי צח ואדום, וכל הענין: **אלהי אבי.** הוא זה **וארוממנהו.** אלהי אבי, לא אני תחלת הקדשה, אלא מחזקת ועומדת לי הקדשה ואלהותו עלי מימי אבותי:
@40 **ה' איש מלחמה.** בעל מלחמות, כמו (רות א ג) איש נעמי, וכל איש ואישך מתרגמין בעל, וכן (מלכים א' ב ב) וחזקת והיית לאיש. לגבור: **ה' שמו.** מלחמותיו לא בכלי זין, אלא בשמו הוא נלחם, כמו שאמר דוד (שמואל א' יז מה) ואנכי בא אליך בשם ה' צבאות. דבר אחר ה' שמו אף בשעה שהוא נלחם ונוקם מאויביו, אוחז הוא במדתו לרחם על ברואיו ולזון את כל באי עולם, ולא כמדת מלכי אדמה כשהוא עוסק במלחמה פונה עצמו מכל עסקיו, ואין בו כח לעשות זו וזו:
@41 **ירה בים.** שדי בימא. שדי לשון יריה, וכן הוא אומר (שמות יט יג) או ירה יירה או אשתדאה ישתדי, והתי''ו משמשת באלו במקום יתפעל: **ומבחר.** שם דבר, כמו (ויקרא טו ט) מרכב, (שם ד) משכב, (שמות יב טז) מקרא קדש: **טבעו.** אין טביעה אלא במקום טיט, כמו (תהלים סט ג) טבעתי ביון מצולה, (ירמיה לח ו) ויטבע ירמיהו בטיט, מלמד שנעשה הים טיט לגמול להם כמדתם, ששעבדו את ישראל בחומר ובלבנים:
@42 **יכסימו.** כמו יכסום, והיו''ד האמצעית יתרה בו, ודרך המקראות בכך, כמו (דברים ח יג) ובקרך וצאנך ירבין, (תהלים לו ט) ירוין מדשן ביתך, והיו''ד ראשונה שמשמעה לשון עתיד כך פרשהו, טבעו בים סוף כדי שיחזרו המים ויכסו אותן. יכסימו אין דומה לו במקרא בנקדתו, ודרכו להיות נקוד יכסימו במלאפו''ם: **כמו אבן.** ובמקום אחר (פסוק י) צללו כעופרת, ובמקום אחר (פסוק ז) יאכלמו כקש, הרשעים כקש הולכים ומטרפין עולין ויורדין, בינונים כאבן, והכשרים כעופרת, שנחו מיד:
@43 **ימינך ימינך.** שתי פעמים, כשישראל עושין את רצונו של מקום השמאל נעשית ימין: **ימינך ה' נאדרי בכח.** להציל את ישראל וימינך השנית תרעץ אויב. ולי נראה אותה ימין עצמה תרעץ אויב, מה שאי אפשר לאדם לעשות שתי מלאכות ביד אחת. ופשוטו של מקרא ימינך הנאדרת בכח מה מלאכתה, ימינך היא תרעץ אויב, וכמה מקראות דגמתו (תהלים צב י) כי הנה אויביך ה' כי הנה אויביך יאבדו, (תהלים צד ג) עד מתי רשעים ה' עד מתי רשעים יעלזו, (תהלים צג ג) נשאו נהרות ה' נשאו נהרות קולם, (תהלים קטו א) לא לנו ה' לא לנו, (הושע ב כג) אענה נאם ה' אענה את השמים, (שופטים ה ג) אנכי לה' אנכי אשירה, (תהלים קכד א. ב) לולי ה' וכו' לולי ה' שהיה לנו בקום עלינו אדם, (שופטים ה יב) עורי עורי דבורה עורי עורי דברי שיר, (ישעי' כו ו) תרמסנה רגל רגלי עני, (תהלים קלו כא, כב) ונתן ארצם לנחלה וכו' נחלה לישראל: **נאדרי.** היו''ד יתרה, כמו (איכה א א) רבתי עם שרתי במדינות, (בראשית לא לט) גנבתי יום: **תרעץ אויב.** תמיד היא רועצת ומשברת האויב, ודומה לו (שופטים י ח) וירעצו וירוצצו את בני ישראל, בשופטים. דבר אחר ימינך הנאדרת בכח היא משברת ומלקה אויב:
@44 **וברב גאונך.** אם היד בלבד רועצת האויב, כשהוא מרומם ברוב גאונו, אז יהרס קמיו, ואם ברוב גאונו לבד אויביו נהרסים, קל וחומר כששלח בם חרון אף יאכלמו: **תהרס.** תמיד אתה הורס קמיך הקמים נגדך, ומי הם הקמים כנגדו, אלו הקמים על ישראל, וכן הוא אומר (תהל' פג ג) כי הנה אויביך יהמיון, ומה היא ההמיה, (שם ב) על עמך יערימו סוד, ועל זה קורא אותם אויביו של מקום:
@45 **וברוח אפיך.** היוצא משני נחירים של אף. דבר הכתוב כביכול בשכינה דגמת מלך בשר ודם, כדי להשמיע אזן הבריות כפי ההוה שיוכלו להבין דבר. כשאדם כועס יוצא רוח מנחיריו, וכן (תהלים יח ט) עלה עשן באפו, וכן (איוב ד ט) ומרוח אפו יכלו, וזהו שאמר (ישעיה מח ט) למען שמי אאריך אפי, כשזעפו נח נשמתו ארכה, וכשהוא כועס, נשמתו קצרה, (שם) ותהלתי אחטם לך, ולמען תהלתי אשים חטם באפי לסתום נחירי בפני האף והרוח שלא יצאו, לך בשבילך. אחטם כמו נאקה בחטם במסכת שבת (דף נא ב) כך נראה בעיני. וכל אף וחרון שבמקרא אני אומר כן, (דברים ז ד) חרה אף, כמו (איוב ל ל) ועצמי חרה מני חרב, לשון שרפה ומוקד, שהנחירים מתחממים ונחרים בעת הקצף, וחרון מגזרת חרה, כמו רצון מגזרת רצה, וכן חמה לשון חמימות, על כן הוא אומר (אסתר א יב) וחמתו בערה בו, ובנוח החמה אומר נתקררה דעתו: **נערמו מים.** אנקלוס תרגם לשון ערמימות ולשון צחות המקרא, כמו (שיר השירים ז ג) ערמת חטים, ונצבו כמו נד יוכיח. נערמו מים. ממוקד רוח שיצא מאפיך יבשו המים והם נעשו כמין גלים וכריות של ערמה שהם גבוהים: **כמו נד.** כתרגומו כשור, כחומה: **נד.** לשון צבור וכנוס, כמו (ישעיה יז יא) נד קציר ביום נחלה, (תהלים לג ז) כונס כנד, לא כתיב כנאד אלא כנד, ואלו היה כנד כמו כנאד. וכונס לשון הכנסה, היה לו לכתוב מכנס כבנאד מי הים, אלא כונס לשון אוסף וצובר הוא, וכן (יהושע ג טז) קמו נד אחד, (שם יג) ויעמדו נד אחד, ואין לשון קימה ועמידה בנאדות אלא בחומות וצבורים, ולא מצינו נאד נקוד אלא במלאפו''ם, כמו (תהלים נו ט) שימה דמעתי בנאדך, (שופטים ד יט) את נאד החלב: **קפאו.** כמו (איוב י י) וכגבנה תקפיאני, שהקשו ונעשו כאבנים והמים זורקים את המצרים על האבן בכח ונלחמים בם בכל מיני קושי: **בלב ים.** בחזק הים, ודרך המקראות לדבר כן (דברים ד יא) עד לב השמים, (שמואל ב' יח יד) בלב האלה, לשון עיקרו ותקפו של דבר:
@46 **אמר אויב.** לעמו כשפיתם בדברים, ארדוף ואשיגם ואחלק שלל עם שרי ועבדי: **תמלאמו.** תתמלא מהם: **נפשי.** רוחי ורצוני. ואל תתמה על תבה המדברת בשתים. תמלאמו תמלא מהם, יש הרבה כלשון הזה (שופטים א טו) כי ארץ הנגב נתתני, כמו נתת לי. (בראשית לז ד) ולא יכלו דברו לשלום, כמו דבר עמו. (ירמיה י כ) בני יצאוני, כמו יצאו ממני. (איוב לא לז) מספר צעדי אגידנו, כמו אגיד לו, אף כאן תמלאמו. תמלא נפשי מהם: **אריק חרבי.** אשלוף, ועל שם שהוא מריק את התער בשליפתו ונשאר ריק נופל בו לשון הרקה, כמו (בראשית מב לה) מריקים שקיהם, (ירמיה מח יב) וכליו יריקו. ואם תאמר אין לשון ריקות נופל על היוצא, אלא על התיק ועל השק ועל הכלי שיצא ממנה, אבל לא על החרב ועל היין, ולדחוק ולפרש אריק חרבי, כלשון (בראשית יד יד) וירק את חניכיו. אזדיין בחרבי, מצינו הלשון מוסב אף על היוצא (שיר השירים א ג) שמן תורק, (ירמיה מח יא) ולא הורק מכלי אל כלי, לא הורק הכלי אין כתיב כאן אלא לא הורק היין מכלי אל כלי, מצינו הלשון מוסב על היין. וכן (יחזקאל כח ז) והריקו חרבותם על יפי חכמתך, דחירם: **תורישמו.** לשון רישות ודלות, כמו (שמואל א' ב ז) מוריש ומעשיר:
@47 **נשפת.** לשון הפחה, וכן (ישעיה מ כד) וגם נשף בהם: **צללו.** שקעו, עמקו, לשון (תהלים סט ג) מצולה: **כעופרת.** אבר פלו''ם בלעז :
@48 **באלם.** בחזקים, כמו (יחזקאל יז יג) ואת אילי הארץ לקח, (תהלים כב כ) אילותי לעזרתי חושה: **נורא תהלת.** יראוי מלהגיד תהלותיו פן ימעטו, כמו שכתוב (שם סה ב) לך דמיה תהלה:
@49 **נטית ימינך.** כשהקדוש ברוך הוא נוטה ידו הרשעים כלים ונופלים, לפי שהכל נתון בידו נופלים בהטיתה וכן הוא אומר (ישעיה לא ג) וה' יטה ידו וכשל עוזר ונפל עזר. משל לכלי זכוכית הנתונים בידי אדם, מטה ידו מעט והן נופלין ומשתברין: **תבלעמו ארץ.** מכאן שזכו לקבורה בשכר שאמרו (לעיל ט כז) ה' הצדיק:
@50 **נהלת.** לשון מנהל, ואונקלוס תרגם לשון נושא וסובל, ולא דקדק לפרש אחר לשון העברית:
@51 **ירגזון.** מתרגזין: **ישבי פלשת.** מפני שהרגו את בני אפרים שמהרו את הקץ ויצאו בחזקה, כמפורש בדברי הימים (דברי הימים א' ז כא) והרגום אנשי גת:
@52 **אלופי אדום אילי מואב.** והלא לא היה להם לירא כלום, שהרי לא עליהם הולכים, אלא מפני אנינות שהיו מתאוננים ומצטערים על כבודם של ישראל: **נמגו.** נמסו, כמו (תהלים סה יא) ברביבים תמגגנה. אמרו עלינו הם באים לכלותינו ולירש את ארצנו:
@53 **תפל עליהם אימתה.** על הרחוקים: **ופחד.** על הקרובים, כענין שנאמר (יהושע ב י) כי שמענו את אשר הוביש וגו' : **עד יעבר עד יעבר.** כתרגומו: **קנית.** חבבת משאר אמות, כחפץ הקנוי בדמים יקרים, שחביב על האדם:
@54 **תבאמו.** נתנבא משה שלא יכנס לארץ לכך לא נאמר תביאנו: **מכון לשבתך.** מקדש של מטה מכון כנגד כסא של מעלה אשר פעלת: **מקדש.** הטעם עליו זקף גדול להפרידו מתבת השם של אחריו המקדש אשר כוננו ידיך ה'. חביב בית המקדש שהעולם נברא ביד אחת, שנאמר (ישע' מח יג) אף ידי יסדה ארץ, ומקדש בשתי ידים. ואימתי יבנה בשתי ידים, בזמן שה' ימלך לעלם ועד, לעתיד לבא שכל המלוכה שלו:
@55 **לעלם ועד.** לשון עולמות הוא והוי''ו בו יסוד לפיכך היא פתוחה, אבל (ירמיה כט כג) ואנכי היודע ועד, שהוי''ו בו שמוש, קמוצה היא:
@56 **כי בא סוס פרעה.** כאשר בא:
@57 **ותקח מרים הנביאה.** היכן נתנבאה כשהיתה אחות אהרן, קדם שנלד משה, אמרה עתידה אמי שתלד בן וכו' , כדאיתא בסוטה (דף יג א) . דבר אחר אחות אהרן לפי שמסר נפשו עליה כשנצטרעה, נקראת על שמו: **את התף.** כלי של מיני זמר: **בתפים ובמחלת.** מבטחות היו צדקניות שבדור שהקדוש ברוך הוא עושה להם נסים והוציאו תפים ממצרים:
@58 **ותען להם מרים.** משה אמר שירה לאנשים, הוא אומר והם עונין אחריו, ומרים אמרה שירה לנשים:
@59 **ויסע משה.** הסיען בעל כרחם שעטרו מצרים סוסיהם בתכשיטי זהב וכסף ואבנים טובות, והיו ישראל מוצאין אותם בים, וגדולה היתה בזת הים מבזת מצרים, שנאמר (שיר השירים א יא) תורי זהב נעשה לך עם נקדות הכסף, לפיכך הצרך להסיען בעל כרחם:
@60 **ויבאו מרתה.** כמו למרה, ה''א בסוף תבה במקום למ''ד בתחלתה, והתי''ו היא במקום ה''א הנשרשת בתיבת מרה, ובסמיכתה כשהיא נדבקת לה''א, שהוא מוסיף במקום הלמ''ד, תהפך הה''א של שרש לתי''ו, וכן כל ה''א שהיא שרש בתבה, תתהפך לתי''ו בסמיכתה, כמו (ישעיה כז ד) חמה אין לי, (אסתר א יב) וחמתו בערה בו, הרי ה''א של שרש נהפכת לתי''ו, מפני שנסמכת אל הו''ו הנוספת, וכן (ויקרא כה מד) עבד ואמה, (בראשית ל ג) הנה אמתי בלהה, (שם ב ז) לנפש חיה, (איוב לג כ) וזהמתו חיתו לחם, (שופטים ד ה) בין הרמה, (שמואל א' ז יז) ותשובתו הרמתה:
@61 **וילנו.** לשון נפעל הוא וכן התרגום לשון נפעל הוא ואתרעמו. כן דרך לשון תלנה להסב הדבור אל האדם מתלונן מתרועם, ולא אמר, לונן, רועם, וכן יאמר הלועז דיקומפליינש''ט שי''י , מוסב הדבור אליו באמרו שי''י [עצמו] :
@62 **שם שם לו.** במרה נתן להם מקצת פרשיות של תורה שיתעסקו בהם, שבת ופרה אדמה ודינין: **ושם נסהו.** לעם, וראה קשי ערפן שלא נמלכו במשה בלשון יפה, בקש עלינו רחמים שיהיה לנו מים לשתות, אלא נתלוננו:
@63 **אם שמוע תשמע.** זו קבלה שיקבלו עליהם: **תעשה.** היא עשיה: **והאזנת.** תטה אזנים לדקדק בהם: **כל חקיו.** דברים שאינן אלא גזרת מלך בלא שום טעם, ויצר הרע מקנטר עליהם מה אסור באלו, למה נאסרו, כגון לבישת כלאים ואכילת חזיר ופרה אדמה וכיוצא בהם: **לא אשים עליך.** ואם אשים הרי היא כלא הושמה, כי אני ה' רופאך, זהו מדרשו. ולפי פשוטו כי אני ה' רופאך ומלמדך תורה ומצות למען תנצל מהם, כרופא הזה האומר לאדם אל תאכל דבר זה פן יביאך לידי חולי זה וכן הוא אומר (משלי ג ח) רפאות תהי לשרך:
@64 **שתים עשרה עינת מים.** כנגד שנים עשר שבטים נזדמנו להם: **ושבעים תמרים.** כנגד שבעים זקנים:
@65 **בחמשה עשר יום.** נתפרש היום של חניה זו, לפי שבו ביום כלתה החררה שהוציאו ממצרים והצרכו למן, למדנו שאכלו משירי הבצק [משירי המצה] ששים ואחת סעודות, וירד להם מן בששה עשר באיר ויום ראשון בשבת היה, כדאיתא במסכת שבת (דף פז ב) :
@66 **וילונו.** לפי שכלה הלחם:
@67 **מי יתן מותנו.** שנמות, ואינו שם דבר כמו מותנו אלא כמו עשותנו, חנותנו, שובנו, לעשות אנחנו, לחנות אנחנו, למות אנחנו. ותרגומו לוי דמיתנא, כמו (במדבר יד ב) לו מתנו, הלואי והיינו מתים:
@68 **דבר יום ביומו.** צורך אכילת יום ילקטו ביומו, ולא ילקטו היום לצורך מחר: **למען אנסנו הילך בתורתי.** אם ישמרו מצות התלויות בו, שלא יותירו ממנו ולא יצאו בשבת ללקוט:
@69 **והיה משנה.** ליום ולמחרת: **משנה.** על שהיו רגילים ללקוט יום יום של שאר ימות השבוע. ואומר אני אשר יביאו והיה משנה, לאחר שיביאו ימצאו משנה במדידה על אשר ילקטו וימדו יום יום וזהו (להלן פסוק כב) לקטו לחם משנה, בלקיטתו היה נמצא לחם משנה. וזהו (להלן פסוק כט) על כן הוא נותן לכם ביום הששי לחם יומים, נותן לכם ברכה פוישו''ן [שפע] בבית למלאות העמר פעמים ללחם יומים:
@70 **ערב.** כמו לערב: **וידעתם כי ה' הוציא אתכם מארץ מצרים.** לפי שאמרתם לנו כי הוצאתם אותנו, תדעו כי לא אנחנו המוציאים אלא ה' הוציא אתכם, שיגיז לכם את השליו:
@71 **ובקר וראיתם.** לא על הכבוד שנאמר (להלן פסוק י) והנה כבוד ה' נראה בענן, נאמר, אלא כך אמר להם ערב וידעתם כי היכולת בידו לתן תאותכם ובשר יתן, אך לא בפנים מאירות יתננה לכם, כי שלא כהוגן שאלתם אותו ומכרס מלאה, והלחם ששאלתם לצורך, בירידתו לבקר תראו את כבוד אור פניו שיורידהו לכם דרך חבה בבקר, שיש שהות להכינו וטל מלמעלה וטל מלמטה כמנח בקפסא: **את תלנתיכם על ה'.** כמו אשר על ה': **ונחנו מה.** מה אנחנו חשובין: **כי תלינו עלינו.** שתרעימו עלינו את הכל, את בניכם ונשיכם ובנותיכם וערב רב, ועל כרחי אני זקוק לפרש תלינו בלשון תפעילו מפני דגשותו וקריתו, שאלו היה רפה הייתי מפרשו בלשון תפעלו, כמו (שמות יז ג) וילן העם על משה, או אם היה דגוש ואין בו יו''ד ונקרא תלונו, הייתי מפרשו לשון תתלוננו, עכשיו הוא משמע תלינו את אחרים, כמו במרגלים (במדבר יד לו) וילינו עליו את כל העדה:
@72 **בשר לאכל.** ולא לשבע, למדה תורה דרך ארץ שאין אוכלין בשר לשבע. ומה ראה להוריד לחם בבקר ובשר בערב, לפי שהלחם שאלו כהוגן, שאי אפשר לו לאדם בלא לחם, אבל בשר שאלו שלא כהוגן, שהרבה בהמות היו להם. ועוד, שהיה אפשר להם בלא בשר, לפיכך נתן להם בשעת טרח, שלא כהוגן: **אשר אתם מלינם עליו.** את האחרים השומעים אתכם מתלוננים:
@73 **קרבו.** למקום שהענן ירד:
@77 **השלו.** מין עוף ושמן מאד: **היתה שכבת הטל.** הטל שוכב על המן ובמקום אחר הוא אומר (במדבר יא ט) וברדת הטל וגו' הטל יורד על הארץ והמן יורד עליו, וחוזר ויורד טל עליו והרי הוא כמנח בקפסא:
@78 **ותעל שכבת הטל** וגו' **.** כשהחמה זורחת עולה הטל שעל המן לקראת החמה, כדרך טל עולה לקראת החמה, אף אם תמלא שפופרת של ביצה טל, ותסתום את פיה ותניחה בחמה, היא עולה מאליה באויר. ורבותינו דרשו שהטל עולה מן הארץ באויר, וכעלות שכבת הטל נתגלה המן וראו והנה על פני המדבר וגו' : **דק.** דבר דק: **מחספס.** מגלה, ואין דומה לו במקרא. ויש לפרש מחספס לשון חפיסא ודלוסקמא שבלשון משנה. כשנתגלה משכבת הטל ראו שהיה דבר דק מחספס בתוכו בין שתי שכבות הטל. ואונקלוס תרגם מקלף, לשון (בראשית ל לז) מחשוף הלבן: **ככפר.** כפור ייליד''ה בלע''ז דעדק כגיר (ישעיה כז ט) כאבני גיר והוא מין צבע שחור, כדאמרינן גבי כסוי הדם (חולין פח ב) הגיר והזרניך. דעדק כגיר כגלידא על ארעא, דק היה כגיר ושוכב מגלד כקרח על הארץ. וכן פרוש דק ככפור, שטוח קלוש ומחבר כגליד. דק טינבי''ש בלעז , שהיה מגליד גלד דק מלמעלה. וכגיר שתרגם אנקלוס, תוספת הוא על לשון העברית, ואין לו תבה בפסוק:
@79 **מן הוא.** הכנת מזון הוא, כמו (דניאל א ה) וימן להם המלך: **כי לא ידעו מה הוא.** שיקראוהו בשמו:
@80 **עמר.** שם מדה: **מספר נפשתיכם.** כפי מנין נפשות שיש לאיש באהלו תקחו עמר לכל גלגלת:
@81 **המרבה והממעיט.** יש שלקטו הרבה ויש שלקטו מעט וכשבאו לביתם ומדדו בעומר, איש איש מה שלקטו, ומצאו שהמרבה ללקוט לא העדיף על עמר לגלגלת אשר באהלו, והממעיט ללקוט לא מצא חסר מעומר לגלגלת, וזהו נס גדול שנעשה בו:
@84 **ויותרו אנשים.** דתן ואבירם: **וירם תולעים.** לשון רמה: **ויבאש.** הרי זה מקרא הפוך, שתחלה הבאיש ולבסוף התליע, כענין שנאמר (פסוק כד) ולא הבאיש ורמה לא היתה בו, וכן דרך כל המתליעים:
@85 **וחם השמש ונמס.** הנשאר בשדה נמוח (י''ג: נמוח) ונעשה נחלים, ושותין ממנו אילים וצבאים, ואמות העולם צדין מהם וטועמין בהם טעם מן, ויודעין מה שבחן של ישראל. ותרגומו של נמס פשר, לשון פושרין, על ידי השמש מתחמם ומפשיר דישטיפרי''ר ודגמתו בסנהדרין [ סז ] בסוף ארבע מיתות:
@86 **לקטו לחם משנה.** כשמדדו את לקיטתם באהליהם מצאו כפלים שני העמר לאחד. ומדרש אגדה לחם משנה משנה. אותו היום נשתנה לשבח בריחו וטעמו: **ויגידו למשה.** שאלוהו מה היום מיומים, ומכאן יש ללמוד שעדין לא הגיד להם משה פרשת שבת שנצטוה לומר להם (פסוק ה) והיה ביום הששי והכינו וגו' , עד ששאלו את זאת, אמר להם (פסוק כג) הוא אשר דבר ה', שנצטויתי לומר לכם, ולכך ענשו הכתוב, שאמר לו (פסוק כח) עד אנה מאנתם, ולא הוציאו מן הכלל:
@87 **את אשר תאפו אפו.** מה שאתם רוצים לאפות בתנור, אפו היום, הכל לשני ימים, ומה שאתם צריכים לבשל ממנו במים, בשלו היום. לשון אפיה נופל בלחם, ולשון בשול בתבשיל: **למשמרת.** לגניזה:
@89 **ויאמר משה אכלהו היום כי שבת היום.** שחרית שהיו רגילים לצאת וללקוט, באו לשאול אם נצא אם לאו, אמר להם את שבידכם אכלו. לערב חזרו לפניו ושאלוהו מהו לצאת, אמר להם שבת היום. ראה אותם דואגים שמא פסק המן ולא ירד עוד, אמר להם היום לא תמצאהו. מה תלמוד לומר היום, היום לא תמצאהו אבל מחר תמצאהו:
@90 **וביום השביעי שבת.** שבת הוא, המן לא יהיה בו, ולא בא הכתוב אלא לרבות יום הכפורים וימים טובים:
@92 **עד אנה מאנתם.** משל הדיוט הוא, בהדי הוצא לקי כרבא, על ידי הרשעים מתגנין הכשרין:
@93 **ראו.** בעיניכם כי ה' בכבודו מזהיר אתכם על השבת, שהרי נס נעשה בכל ערב שבת לתת לכם לחם יומים: **שבו איש תחתיו.** מכאן סמכו חכמים ארבע אמות ליוצא חוץ לתחום: **אל יצא איש ממקמו.** אלו אלפים אמה של תחום שבת, ולא במפורש, שאין תחומין אלא מדברי סופרים, ועיקרו של מקרא על לוקטי המן נאמר:
@95 **והוא כזרע גד לבן.** עשב ששמו אליינדר''א [כוסבר] וזרע שלו עגול ואינו לבן, והמן היה לבן, ואינו נמשל לזרע גד אלא לענין העגול כזרע גד היה, והוא לבן: **כצפיחת.** בצק שמטגנין אותו בדבש וקורין לו אסקריטון בלשון משנה והוא תרגום של אנקלוס:
@96 **למשמרת.** לגניזה: **לדרתיכם.** בימי ירמיהו כשהיה ירמיהו מוכיחם, למה אין אתם עוסקים בתורה והם אומרים נניח מלאכתנו ונעסוק בתורה, מהיכן נתפרנס, הוציא להם צנצנת המן ואמר להם (ירמיה ב לא) הדור אתם ראו דבר ה', שמעו לא נאמר אלא ראו, בזה נתפרנסו אבותיכם, הרבה שלוחין יש לו למקום להכין מזון ליראיו:
@97 **צנצנת.** צלוחית של חרס, כתרגומו: **והנח אתו לפני ה'.** לפני הארון, ולא נאמר מקרא זה עד שנבנה אהל מועד, אלא שנכתב כאן בפרשת המן:
@99 **ארבעים שנה.** והלא חסר שלשים יום, שהרי בחמשה עשר באיר ירד להם המן תחלה, ובחמשה עשר בניסן פסק, שנאמר (יהושע ה יב) וישבת המן ממחרת, אלא מגיד שהעוגות שהוציאו ישראל ממצרים טעמו בהם טעם מן: **אל ארץ נושבת.** לאחר שעברו את הירדן שאותה שבעבר הירדן מישבת וטובה, שנאמר (דברים ג כה) אעברה נא ואראה את הארץ הטובה אשר בעבר הירדן, ותרגום של נושבת יתבתא, רצה לומר מישבת: **אל קצה ארץ כנען.** בתחלת הגבול, קדם שעברו את הירדן, והוא ערבות מואב. נמצאו מכחישין זה את זה, אלא בערבות מואב כשמת משה בשבעה באדר פסק המן מלירד, ונסתפקו ממן שלקטו בו ביום עד שהקריבו העמר בששה עשר בניסן, שנאמר (יהושע ה יא) ויאכלו מעבור הארץ ממחרת הפסח:
@100 **עשרית האיפה.** האיפה שלש סאין, והסאה ששה קבין והקב ארבעה לוגין והלוג שש ביצים נמצא עשירית האיפה ארבעים ושלש ביצים וחמש ביצה והוא שעור לחלה ולמנחות:
@102 **מה תנסון.** לומר היוכל לתת מים בארץ ציה:
@104 **עוד מעט.** אם אמתין עוד מעט וסקלני:
@105 **עבר לפני העם.** וראה אם יסקלוך, למה הוצאת לעז על בני: **וקח אתך מזקני ישראל.** לעדות שיראו שעל ידך המים יוצאים מן הצור, ולא יאמרו מעינות היו שם מימי קדם: **ומטך אשר הכית בו את היאר.** מה תלמוד לומר אשר הכית בו את היאור, אלא שהיו ישראל אומרים על המטה שאינו מוכן אלא לפרענות, בו לקה פרעה ומצרים כמה מכות במצרים ועל הים, לכן נאמר אשר הכית בו את היאר, יראו עתה שאף לטובה הוא מוכן:
@106 **והכית בצור.** על הצור לא נאמר אלא בצור, מכאן שהמטה היה של מין דבר חזק ושמו סנפרינון והצור נבקע מפניו:
@108 **ויבא עמלק** וגו' **.** סמך פרשה זו למקרא זה, לומר תמיד אני ביניכם ומזמן לכל צרכיכם, ואתם אומרים (פסוק ז) היש ה' בקרבנו אם אין, חייכם שהכלב בא ונושך אתכם ואתם צועקים אלי ותדעון היכן אני. משל לאדם שהרכיב בנו על כתפו ויצא לדרך, היה אותו הבן רואה חפץ ואומר, אבא טול חפץ זה ותן לי, והוא נותן לו, וכן שניה וכן שלישית, פגעו באדם אחד, אמר לו אותו הבן ראית את אבא. אמר לו אביו אינך יודע היכן אני, השליכו מעליו ובא הכלב ונשכו:
@109 **בחר לנו.** לי ולך, השוהו לו, מכאן אמרו יהי כבוד תלמידך חביב עליך כשלך וכבוד חברך כמורא רבך, מנין שנאמר (במדבר יב יא) ויאמר אהרן אל משה בי אדני והלא אהרן גדול מאחיו היה ועושה את חברו כרבו. ומורא רבך כמורא שמים מנין, שנאמר (שם יא כח) אדני משה כלאם, כלם מן העולם, חייבין הם כליה, המורדים בך, כאלו מרדו בהקדוש ברוך הוא: **וצא הלחם.** צא מן הענן והלחם בו: **מחר.** בעת המלחמה אנכי נצב: **בחר לנו אנשים.** גבורים ויראי חטא שתהא זכותן מסיעתן. דבר אחר בחר לנו אנשים שיודעין לבטל כשפים לפי שבני עמלק מכשפין היו:
@110 **ומשה אהרן וחור.** מכאן לתענית שצריכים שלשה לעבור לפני התבה, שבתענית היו שרוים: **חור.** בנה של מרים היה וכלב בעלה:
@111 **כאשר ירים משה ידו.** וכי ידיו של משה נוצחות היו המלחמה וכו' כדאיתא בראש השנה (כט א) :
@112 **וידי משה כבדים.** בשביל שנתעצל במצוה ומנה אחר תחתיו, נתיקרו ידיו: **ויקחו.** אהרן וחור: **אבן וישימו תחתיו.** ולא ישב לו על כר וכסת. אמר ישראל שרויין בצער, אף אני אהיה עמהם בצער: **ויהי ידיו אמונה.** ויהי משה ידיו באמונה פרושות השמים בתפלה נאמנה ונכונה: **עד בא השמש.** שהיו עמלקים מחשבין את השעות באצטרולוגיאה באיזו שעה הם נוצחים, והעמיד להם משה חמה וערבב את השעות:
@113 **ויחלש יהושע.** חתך ראשי גבוריו ולא השאיר אלא חלשים שבהם ולא הרגם כלם, מכאן אנו למדין שעשה על פי הדבור של שכינה:
@114 **כתב זאת זכרון.** שבא עמלק להזדוג לישראל קדם לכל האמות: **ושים באזני יהושע.** המכניס את ישראל לארץ, שיצוה את ישראל לשלם לו את גמולו, כאן נרמז לו למשה שיהושע מכניס את ישראל לארץ: **כי מחה אמחה.** לכך אני מזהירך כן, כי חפץ אני למחותו:
@115 **ויקרא שמו.** של מזבח: **ה' נסי.** הקדוש ברוך הוא עשה לנו כאן נס גדול, לא שהמזבח קרוי ה', אלא המזכיר שמו של מזבח זוכר את הנס שעשה המקום, ה' הוא נס שלנו:
@116 **ויאמר.** משה: **כי יד על כס יה.** ידו של הקדוש ברוך הוא הרמה לשבע בכסאו להיות לו מלחמה ואיבה בעמלק עולמית, ומהו כס, ולא נאמר כסא, ואף השם נחלק לחציו, נשבע הקדוש ברוך הוא שאין שמו שלם ואין כסאו שלם עד שימחה שמו של עמלק כלו, וכשימחה שמו יהיה השם שלם והכסא שלם, שנאמר (תהלים ט ז) האויב תמו חרבות לנצח, זהו עמלק שכתוב בו (עמוס א יא) ועברתו שמרה נצח, (תהלים שם) וערים נתשת אבד זכרם המה, מהו אומר אחריו (תהלים ט ח) וה' לעולם ישב, הרי השם שלם, (תהלים שם) כונן למשפט כסאו, הרי כסאו שלם:
@117 **אשת לפידות.** שהיתה עושה פתילות למקדש:
@118 **תחת תומר.** תמרים היו לה ביריחו: **בין הרמה ובין בית אל בהר אפרים.** לפי תרגומו של יונתן יש ללמוד שאין מקרא זה כמשמעו, ואין אלו סימני מקום ישיבתה, אלא למדנו שאשה עשירה היתה ומן המקומות האלו היתה פרנסתה, והיא יושבת בעירה, עטרות שמה: **תחת תומר.** תמרים היו לה ביריחו, וכרמים ברמה, וזיתים בבקעת בית אל, שהוא מקום שמן, ועפר חיוור בהר אפרים, ( תרגום: **) 'בטור מלכא', אומר אני שמוכרין אותה ליוצרי חרש.** ויש פותרין: 'עפר חיוור', שדה זרע, כמו ( שביעית ב א ): שדה הלבן:
@119 **הלא צוה.** ביד משה ( דברים כ יז ): כי החרם תחרימם, כך שנויה במכילתא ( בא יב ):
@123 **ויעל ברגליו.** עמו:
@124 **אילון בצעננים.** ( תרגום: ) מישר אגניא, מקום מישר של בצעים, מריש"ק בלע"ז והוא אגניא גבים, כמין גומות שהמים נקבצים שם, 'אגני דארעא מקרון' ( קידושין סא א ):
@126 **מחרושת הגוים אל נחל קישון.** הזעיקם שילכו אל נחל קישון מחרושת הגוים שהוא יושב שם:
@131 **בשמיכה.** תרגם יונתן: בגונכא, ופירש רב האי ( שבת נא א ): גונכא - גלופקרין, קוט"א בלע"ז:
@132 **נאד החלב.** שהחלב מכביד את הגוף להיות נרדם:
@133 **עמוד פתח האהל.** זרזי עצמך בדבר. ויש פותרים: 'עמוד', כמו לעמוד:
@134 **יתד האהל.** קבילי"ל בלע"ז, שתוקעין בארץ עם שיפולי האהל לפושטו: **המקבת.** ( תרגום: ) ארזפתא, מרטי"ל בלע"ז: **בלאט.** ( תרגום: ) ברז, חרש: **ותצנח בארץ.** ( תרגום: ) ונעצת בארעא:
@135 **ברקתו.** ( תרגום: ) בצידעיה, ניל"ה טימפי"ה בלע"ז, ותחבה ברקתו ובארץ:
@139 **בפרע פרעות בישראל בהתנדב עם.** כשבאו פרצות על ישראל שפרצו בהם אויביהם על עזבם את ה', והתנדב העם לשוב בתשובה, מעתה ברכו את ה' על התשועות שעשה:
@140 **אנכי.** אנכי. כפול, שמעתי מדרש אגדה ( ילקוט שמעוני ב מז ) לא קפח הקדוש ברוך הוא שכר תבור וכרמל, שבאו למתן תורה לתת עליהם את התורה וחזרו בבשת הפנים, אמר להם הקדוש ברוך הוא, סוף שאני פורע לכם כפלים, נאמר בסיני ( שמות כ ב ) אנכי ה' אלהיך, בתבור יאמר: **אנכי..**. אנכי, נאמר בסיני ( שם ) אנכי ה' אלהיך, בכרמל יאמר, כפול ( מלכים א יח לט ) ה' הוא האלהים, ה' הוא האלהים, בימי אליהו:
@141 **ה' בצאתך משעיר.** זה מתן תורה, כמה שנאמר ( דברים לג ב ) וזרח משעיר למו, ומה עניינה לכאן, כך אמרה דבורה: קשה היא התורה לפרוש ממנה וטובה היא לדבק בה, שהרי במורא ובגבורה נתנה, ולכך נמסרו ישראל ביד אויביהם על פרישתם הימנה וכשהתנדבו לעסוק בה נושעו, כל זה יש ללמוד מתרגומו של יונתן: **נטפו.** הזילו טל תחיה:
@142 **הרים נזלו.** כמים נוזלים נמוגו: **זה סיני.** כבר מפורש ( שמות יט כ ) מה נראה בו: עשן כולו, וקול, ולפידים ואש מפני ה', והרי זה מקרא קצר 'זה סיני', מה אירע בו, מפני אשר ירד עליו ה':
@143 **בימי שמגר בן ענת בימי יעל.** מלמד שאף יעל שפטה את ישראל בימיה: **חדלו ארחות.** היו יראים ישראל לצאת לדרכם מפני האויבים והיו הולכים דרך עקלתון בהחבא:
@144 **חדלו פרזון.** ערי הפרזי שאין להם חומה חדלו מהיות יושבים בהם מפני אויביהם, ונאספו אל ערי המבצר: **עד שקמתי.** כמו שקמתי, וכן ( שופטים ו יז ): שאתה מדבר עמי:
@145 **יבחר אלהים חדשים אז לחם שערים.** כשבחר לו ישראל אלהים חדשים, אז הוזקקו למלחמה בשעריהם, ראו עתה בהתנדבם, אם יראה בישראל מגן ורומח, שצריך להלחם בארבעים אלף ראשי גייסות שהביא הגוי עליהם, וכולם הממם המקום במלחמת הכוכבים ( פסוק כא ) ונחל קישון גרפם: **שערים.** כמו ( דברים יז ב ) כי ימצא בקרבך באחד שעריך, עיירות:
@146 **לבי.** אני דבורה לחוקקי ישראל, לאהוב את חכמי ישראל שהתנדבו בעם, לאמר: ברכו את ה' ושובו אליו:
@147 **רכבי אתנות צחורות.** הסוחרים והשרים שירכבו מעתה על אתונות לבנות החשובות, מבלי יראה ודאגת אויביהם, ואותן שיושבין על מדין, לשון דיינים, שהיו יראים לעשות משפט בפרהסיא, וכן תרגם יונתן: דהוו מתחברין למיתב על דינא, ואותן שהולכין רגלי על דרך, שיחו וספרו את התשועה הזאת, אשר מקול המחצצים אתכם, אורבים, ליסטים ומוכסין, היושבין גדודים במערכות לארוב בעברי המים, שם יתנו עתה רוכבי האתונות והולכי על דרך את צדקות ה', ומה הן הצדקות ( פסוק יא ) צדקות פרזנו בישראל שהשקיט את ישראל, לשכון פרזון ולצאת מפוזרים ביחידי, שלא באסיפת עם:
@148 **מחצצים.** פתר מנחם: עורכי מלחמה וסודרי קרב, וחברו עם ( משלי ל כז ): **מלך אין לארבה ויצא חצץ כולו, לשון גדודים.** דבר אחר: **מקול מחצצים בין משאבים.** כשהייתם הולכים בין משאבים לשאוב מים, הייתם יראים מקול אבנים, חלוקי הנחל, קיזל"ש בלע"ז, שהעובר עליהם נשמע קולם, והייתם יראים שלא ירגישו בכם אויביכם, מעכשיו אין לחוש על זאת, ומשום הכי מצוה עליכם ליתן הודיה לשמו: **מחצצים.** לשון אבני חלוקי הנחל, כמו ( איכה ג טז ) ויגרס בחצץ: **אז ירדו לשערים.** חזרו לערי מושבותם שברחו מהם ליאסף אל ערי המבצר:
@149 **עורי עורי דבורה.** לשון שבח כפשוטו, התגברי בשירתך. ורבותינו אמרו ( פסחים סו ב ) מפני שנתהללה ואמרה ( פסוק ז ) עד שקמתי דבורה, נסתלקה הימנה רוח הקודש:
@150 **אז ירד שריד לאדירים.** ירד - ירדה, כמו ( ישעיהו מה א ) לרד לפניו גוים, שרידי ישראל רדו באדירי הגוים: **ה' ירד לי בגבורים.** ירדה לי את גבורי הגוים:
@151 **מני אפרים.** מן אפרים יצא שורש יהושע בן נון, לרדות בעמלק לחלש אותו לפי חרב, ומחובר מקרא זה לעליון, לפרש: ה' ירד לי בגבורים, את יהושע הקים לרד בעמלק: **אחריך.** יקום משבט בנימין שאול בן קיש שיגרמנו ויעמם אותו כגחלים עוממות. ויש לפתור: 'בעממיך', בחיל של מאתים אלף רגלי שבא שאול עליהם: **מני מכיר ירדו מחקקים.** שרים גדולים שכבשו את האמורי, אשר כבשו ( דברים ג ד ) ששים עיר כל חבל ארגוב שכבש יאיר:
@152 **ושרי ביששכר.** שרים שביששכר, הם סנהדראות עוסקין בתורה, ( דברי הימים א יא לב ) יודעי בינה לעתים, הם תמיד עם דבורה ללמד בישראל חק ומשפט: **ושרי ביששכר.** יו"ד זו טפילה היא ואינה משמשת כלום, והרי היא כיו"ד ( תהלים ח ח ) בהמות שדי, ( ירמיהו כב יד ) וקרע לו חלוני: **ויששכר כן ברק.** ושאר העם של יששכר, כן הם עם ברק לכל אשר יצוה: **בעמק שלח ברגליו.** שלחם בכל שליחותו, ולאסוף את העם ולכל צרכי המלחמה: **בפלגות ראובן.** אבל בחילוקי לבו של ראובן רבו: **חקקי לב.** ( תרגום: ) נכלי ליבא, ערמומית, ומה היא ערמומיתו, ישב לו בין משפתי המלחמה לשמוע מי נוצח ויהיה עמו:
@153 **שרקות עדרים.** לשמוע קול עדרי המלחמה, למי קול ענות גבורה ולמי קול ענות חלושה:
@154 **בעבר הירדן שכן.** ולא בא אל המלחמה, וכן דן הכניס ממונו בספינות לעמוד ולברוח: **ועל מפרציו.** לשמור פרצות ארצו:
@155 **זבלון עם חרף וגו'.** בזה נפשו והפקיר עצמו למות במלחמה עם ברק, וכן נפתלי על מרומי שדה. על הר תבור:
@156 **בתענך על מי מגדו.** תרגם יונתן: בתענך הוו שרן ומטן על מי מגדו, ראש המחנה בתענך ומגיע עד מי מגידו: **בצע כסף לא לקחו.** חנם באו לעזרת סיסרא, לא בקשו ממנו שכר:
@157 **מן שמים נלחמו.** ואף הקדוש ברוך הוא שלח בם צבאיו שאינם רוצים שום שכר: **ממסלותם.** ראש הכוכב בשמים וסופו בארץ, מכאן אמרו ( תנחומא בראשית ה ) עוביו של רקיע כאויר שבין שמים לארץ, שהכוכב תקוע ברקיע כמין נגר בדלת, מדת ארכו כעביו של רקיע, ומן המקרא שמעיד 'ממסילותם נלחמו', אנו שומעין שעוביו של רקיע כגובה שמים מן הארץ:
@158 **גרפם.** טאטם מן העולם, כמגרפה זו שגורפת את האפר מן הכירה: **נחל קדומים.** שנעשה ערב לים על זה מימות מצרים, כדאיתא בפסחים ( קיח ב ): **תדרכי נפשי.** ברגלים את עוז גבורי כנען:
@159 **הלמו עקבי סוס.** נשתלפו טלפי סוסיהם, שהיה חום הכוכב מרתיח את הטיט והציפורן נשמטה, כמו שמולגין את הרגלים ברותחין והטלפים נשמטים, מתוך שנשתלפו נהלמו הרגלים: **מדהרות דהרות אביריו.** שהיו מרקידים את סוסיהם במלחמה, כמו ( נחום ג ב ) וסוס דהר, הוא לשון הרקדת הסוס:
@160 **אורו מרוז.** אמרי לה כוכבא הוה, ואמרי לה גברא חשיבא הוה ( מועד קטן טז א ), והיה סמוך למקום המלחמה ולא בא: **אמר מלאך ה'.** אמר ברק בשליחותו של הקדוש ברוך הוא: **יושביה.** היושבים בארבע אמות שלו ( שם ) בארבע מאות שפורי שמתיה ברק למרוז: **לעזרת ה'.** כביכול, שמי שהוא עוזר את ישראל, כעוזר את השכינה:
@161 **מנשים באהל.** שרה, שנאמר בה ( בראשית יח ט ) הנה באהל. רבקה, שנאמר בה ( שם כד סז ) ויביאה יצחק האהלה. רחל ולאה, שנאמר בהן ( שם לא לג ) ויצא מאהל לאה וגו': **מנשים באהל תבורך.** יעל. למה - הן ילדו וגידלו, ואם לא יעל הרי הרשע הזה בא ומאבדן, כך הוא בבראשית רבה ( מח טו ). דבר אחר, אף יעל היתה יושבת אהלים, לפיכך הזכיר אותה בברכת אהלים:
@162 **חלב נתנה.** לדעת אם לבו עליו שיבין בין טעם מים לטעם חלב, כן תרגם יונתן: **בספל אדירים.** בספל ששותין בו מים, שהמים נקראו 'אדירים', שנאמר ( שמות טו י ) במים אדירים:
@163 **להלמות עמלים.** סיסרא, שהיה עמל ויגע: **מחקה.** לשון חיקוי: **ומחצה.** לשון מחץ: **וחלפה.** יוצא מצד אחר:
@165 **ותיבב.** לשון דבור, כמו ( ישעיהו יז יט ) ניב שפתים. ורבותינו פירשוהו ( ראש השנה לג ב ) לשון גניחה, כתרועה, דמתרגמינן 'יבבא' ( ויקרא כג כד ). ואני אומר: לשון ראייה, כמו ( זכריה ב ב ) בבת עיני, וכן חברו מנחם: **אשנב.** חלון:
@166 **חכמות שרותיה תענינה.** החכמות שבשרותיה, לכך נקוד חי"ת פת"ח, חכמות שהוא שם דבר נקוד חט"ף קמ"ץ, כמו ( משלי יד א ) ראמות לאויל חכמות, וזה נקוד חכמות, וכן ( שם יד א ) חכמות נשים בנתה ביתה, חכמות שבנשים: **תענינה.** דגשות של נו"ן משמשת במקום נו"ן שלישית, ופתרונו תענינה אותה, דגשות נו"ן משמשת במקום 'אותה', כמו ( ויקרא ו יד ) מרבכת תביאנה: **אף היא תשיב אמריה.** תנחומין לעצמה: מה אני מתמה תמיה על עכוב בני:
@167 **הלא ימצאו יחלקו שלל.** והוא מעכבן: **רחמתים לראש גבר.** מענים נשים יפות בישראל, וכל איש מהם יש לו במטתו שתים ושלש נשים:
@168 **כן יאבדו.** דבורה אמרה: תנחומין של הבל הן לה, כן יאבדו כל אויביך ה', כאשר אבד הוא: **ואהביו כצאת השמש בגברתו.** לעתיד לבא, ( ישעיהו ל כו ) שבעתים כאור שבעת הימים, שהיא על אחת שלש מאות וארבעים ושלש כמספר ארבעים ותשע שביעיות: **ותשקט הארץ.** אין זה מדברי דבורה אלא מדברי כותב הספר:

@10 **אכבדה בפרעה ובכל חילו.** ר"ל שכבר אתכבד ואתעלה בעבור מה שאביא בפרעה ובחילו. מהמכ' העצומה כי אז יכירו יש' כבודי וגבורתי ומעלתי לעשות כל מה שאחפוץ:
@10 **וידעו מצרים כי אני יי'.** ר"ל שלא יהיה לישראל לירוא שירדפו עוד מצרים אחריהם כי כבר יתבאר להם שאני יי' במה שאביא עליהם מהמכה העצומה וייראו מפני זה מרדוף עוד אחרי בני ישראל וזהו התועלת המגיע לישראל כאשר ידעו המצרים הפלגת גבורת השם יתעלה כי הוא נלחם לישר' כי לא היתה הכונה בזה להביא המצרים לאמונת הש"י וזה מבואר בנפשו:
@12 **ויאסור את רכבו.** ר"ל בצווי כי אין מחוק המלך לאסור רכבו או אולי עשה זה לרוב הזריזו' לרדוף אחריהם:
@12 **ואת עמו לקח עמו.** יתכן שפתה אותם והסיתם לרדוף אחריהם כי הם היו יראים מזה למה שראו מהנפלאות אשר עשה השם יתע' בעבורם ואפשר שהכריח אותם לרדוף אחריהם ולה אמר ואת עמו לקח עמו:
@13 **ושלישים.** ר"ל גבורים ושרים:
@14 **ובני ישראל יוצאים ביד רמה.** ר"ל שלא היו הולכים כדמות בורחים:
@16 **ופרעה הקריב.** ר"ל שהנהיג מחנהו במרוצה חזקה באופן שהקריבו מאד לישראל כי טוב לנו עבוד את מצרים וגומר. יתכן שאמרו לו זה ליראתם שיהיה אלוהי ישראל הוא האלוה הפועל הרעות כמו שהיה חושב פרעה במה שאמר לישראל ראו כי רעה נגד פניכם כמו שביארנו במה שקדם ולזה השיב להם משה שיתיצבו ויראו את ישועת יי' אשר יעשה להם היום בהפך מה שהיו חושבים ממנו שיהיה פועל הרעות לבד ואפשר גם כן שישראל היו יראים שירדוף אחריהם פרעה מלך מצרים כשיראה שלא ישובו ולזה היו יראים שימותו במדבר והשיב להם משה שלא ייראו מזה כי השם ית' יסבב שלא יוסיפו המצרים לרדוף אחריהם ולזה אמר להם שלא יוסיפו לראות המצרים עוד עד עולם כי כבר ידעו המצרים כח השם יתע' וגבורתו בהכבדו בפרעה ברכבו ובפרשיו:
@20 **יי' ילחם לכם ואתם תחרישון.** יתכן שצוה להם שלא יצעקו ולא ידברו כדי שלא ירגישו המצרים שהם קרובים להם מאד ויורו להם חצים או יזיקו להם באופן אחר ולזאת הסבה סבב השם יתע' בענן שיהיה בין המצרים וביניהם בדרך שלא יראו המצרים את ישראל ולא יזיקום:
@21 **מה תצעק אלי.** יתכן שמשה היה צועק לשם יתעלה שיציל את ישראל מיד מצרים שהיו קרובים להם מאד ואף גם זאת שכבר ייעד השם יתע' למשה שכבר יכבד לב פרעה ובכל חילו והנה עם כל זה לא נמנע מלהתפלל לשם יתע' כי זה יהיה כלי אל שיחדש השם יתע' זה המופת אז על ידו להיותו דבק בשם יתעלה בעת התפילה. וידמה שכבר אמר השם יתע' למשה שלא יצטרך לו לזעוק אל יי' להכין עצמו אל שיהיה דבק לשם יתעלה בעבור שיהיה ראוי שיעשה זה המופת הנפלא על ידו כי היה דבק בו תמיד:
@25 **ויסע מלאך האלהים ההולך לפני מחנה ישראל.** יתכן שקרא מלאך האלהים הכח והשופע מאת השם יתע' שישפע ממנו זה הפלא העצום. ר"ל עמוד הענן ועמוד האש ואפשר שיהיה מלאך האלהים הנזכר בזה הפסוק הוא משה כי הנביא יקרא מלאך כמו שקדם ואחשוב שעשה זה לפי שיש לנביא רושם בחדוש האותות והנפלאו' כמו שהתבאר בששי מספר מ"י ועוד כי היה בזה תועלת לישראל שלא ייראו מפרעה ומעמו כי הנביא שם עצמו במקום אשר היה בו מהסכנה יותר ולזה הוא מבואר שהוא היה יודע בלי ספק שלא יקרם שום נזק בזה ועוד כי לפי שהנביא היה יותר מושגח לעוצם התדבקותו בשם יתע' הנה היה ראוי שיהיה הוא אחרון כי בזה יעשה במלחמה שישמו מול פני המלחמה החזקה היותר גבורים:
@26 **ויהי הענן והחשך.** ר"ל שכבר התקבצו שם שתי סבות להציל ישראל מיד המצרי' וזה כי כבר היה ענן מפסיק ביניהם אשר ימנעם מראותם והנה חשך הלילה ג"כ מנעם מראות אותם:
@26 **ויאר את הלילה.** ר"ל שכבר האיר השם יתע' הלילה לישר' בעמוד אש וזה ג"כ סבה שלישית להציל ישראל:
@27 **ויולך יי' את הים ברוח קדי' עזה כל הלילה.** ראוי שתדע כי השם כשיעשה המופתים ישתדל להמציא להם סבות אשר בהם יהיה יותר מעט מן הזרות אצל הטבע כמו שקדם וכבר ביארנו זה בששי ממ"י. ולזאת הסבה המציא הש' יתעלה ע"ד המופת רוח קדים עזה אשר היא מנגבת ומעתקת המים אל הצד המערבי באופן שחדש להם מקום מגולה בים והיומי הים מימינו ומשמאלו כי המקום ההוא יותר גבוה ולזה נשלם לו ההגלות עם השאר המים מימינו ומשמאלו וזה הוא הרצון בהם שאמר והמים להם חומה מימינם ומשמאלם לא שיהיו המים גבוהים מימין ומשמאל ולא יהיו נגרים שאם היה הענין כן לא יהיה מבא לרוח הקדים לחדוש זה המופת אלא שעם כל זה היו המים גבוהים בצד המערבי כי הרוח העתיקם שם והיה מונע אותם תמיד מהיותם נגרים ולזה הוליך יי' רוח קדים עזה כל הלילה. והנה קרא המים חומה. ואם אינם גבוהים לפי שהם היו מונעים המצרים מלבא עליהם מימינם ומשמאלם ולא היו יכולים ללכת כי אם מאחריהם. ומאחריהם היה הענן לחומר ביניהם:
@30 **וישקף יי' אל מחנה מצרים.** יתכן שהמציא השם יתע' אז במחנה מצרים ענן עם איד קיטורי היה יורד ממנו מטר וברקים לבהלם עם שבזה נתלחלח המקום המגולה אשר בו היו מהים ולזה לא היו יכולים הסוסים ללכת והם הסירו אופן מרכבותיו להקל מהסוסים כדי שיוכלו לברוח ולצאת מהים ועם כל זה לא הועיל להם כי כבר היו הולכים שם בכבדות לרוב הטיט שהיה בים ואפשר שיהיה הרצון במה שאמר בעמוד אש וענן כי במחנה מצרים אשר הגביל אותו תמיד עמוד האש והענן שהיה בין מחנה ישראל ובין מחנה מצרים חדש השם יתע' מה שיהם את מחנה מצרים וזה עם מטר סוחף וברקים כמו שאמר דוד וישלח חציו ויפיצם וברקים רב ויהומם או שהביא השם רוח מקבלת לרוח הראשונה הפכה המים שבאו לצד המערבי על מחנ' מצרים ואז הסירו המצרים אופן מרכבתיהם לברוח וזה הוא מה שאמר אחר זה נטה ידך על הים וישובו המים על מצרים על רכבו ועל פרשיו וזה היה בתכלית הפלא כי במקום שהיו בו ישראל היתה מנשבת רוח הקדים ובמקום שהיו בו המצרים היה מנשבת הרוח המקבלת לה עד שנשלמה בזה האופן ההצלה לישראל בעת שהיו בו המצרים טובעים כמו שאמר אחר זה וישובו המים ויכסו את הרכב ואת הפרשים לכל חיל פרעה הבאים אחריהם בים ולא נשאר בהם עד אחד ובני ישראל הלכו ביבשה בתוך הים. ר"ל כי בעת שהיו המצרים טובעים היו ישראל הולכים ביבשה בתוך הים:
@33 **וינער יי' את מצרים בתוך הים.** הרצון בזה כי הרוח שדחה עליהם מי הים בלבלם ונערם והוליכם אל עומק מי הים לרוב הדחייה אשר היתה שם וזהו מה שאמר ירדו במצולות כמו אבן ואפשר היותו מענין צעקה כטעם נערו כגורי האריו' ר"ל שהם היו צועקים מאד בראותם בא עליהם מי הים והנה בזה התועלת לישראל להודיעם כי הם היו אחריהם ושכבר היו טובעים וזה שאם לא היה הענין כן הנה מפני שהיה הענן ביניהם לא יתאמת לישראל שהיו טובעים המצרים כי אולי יחשבו שלא ירדפו אחריהם בתוך הים אבל שבו מרדוף ואולם כששמעו אותם צועקים נתברר להם שהם היו בים אחריהם ושכבר טבעו שם כלם כי לא ראוי שנשאר מהמחנה ההוא דבר:
@36 **ויושע יי' ביום ההוא.** ר"ל שביום ההוא נשלמה התשועה לישראל מיד מצרים כי זה יהיה סבה שלא יוסיפו המצרים עוד לרדוף אחריהם:
@36 **וירא ישראל את מצרים מת על שפת הים.** ר"ל שהחלק מישראל שיצאו מהים והיו על שפת הים היו רואים המצרים טובעים בים. או יהיה הרצון בזה שהים הוציא הטובעים ממחנה מצרים לשפת הים וראו ישראל המצרים מתים על שפת הים והביאור הראשון נראה לנו יותר:
@37 **וייראו העם את יי'.** ר"ל שכבר נתברר להם כח ה' וגבורתו ולזה ייראו ממנו:
@37 **ויאמינו ביי' ובמשה עבדו.** ר"ל שאז האמינו בשם יתע' בכל מה שיעד להם והאמינו במשה עבדו בכל מה שאמר להם בשמו כי אז נתברר להם כי הוא שליח נאמן לשם יתעלה:
@38 **אשירה ליי'.** ר"ל אדבר בתאריו דרך שיר והמשל כי לא אוכל לדבר בעצמותו:
@38 **כי גאה גאה.** מאד:
@38 **רמה בים.** השליך וירה. והנה אמר זה על צד ההפלגה להורות על מהירות הכנסם בים וטבעם בו כי השם יתע' סבב להביאם אל שירדפו אחרי בני ישראל תוך הים והנה רדפו שם אחריה' במהירו' נפלא לפי מה שהיה אפשר להם וזה היה סבה שטבע כלם בים ולזה אמר רמה בים כי השם יתע' הניעם במהירות ללכת בים כמו שיתנועע החץ במהירות כשיורו אותו:
@39 **עזי וזמרת יה.** יתכן שתהיה היו"ד במלת עזי נוספת ויהיה וזמרת כמו וזמרה כי כבר ימצא בלשון שמות מוכרתים יבואו בתואר סמוכי' נפל אשת' אתן שנת. וכמוהם רבים. והרצון יהיה בזה כי השם הוא עוז וזמרה וכן פירשו רז"ל במכילתא ויהי העוז מענין הבאת העונש הנפלא כמו שקרא המכות הנפלאים שהכה במצרים חוזק יד ויד חזקה ויהיה זמרה מענין שבח וגאות ורוממות כמו מזמרת הארץ. ויהיה הרצון בזה שהשם יתע' הוא תכלית העוז להתגבר על אויביו כי לא יבצר ממנו כל אשר ירצה לעשות והוא גם כן תכלית הטוב והשבח כי פעולותיו תמצאנה בתכלית מה שאפשר מהחכמ' וטוב הסדור. והנה ירצה בזה השם יתעלה היה עוז למצרים להתגבר עליהם להשחיתם והיה זמרה וטוב לישראל באופן שהיה לו לישועה בדבר ההוא בעינו שהשחית בו המצרים או יהיה וזמרת סמוך. ויהיה הרצון בזה שגבורת יה וטובו רמה בים סוס ורוכבו היה לי לישועה ר"ל שהפועל האחד בעינו היה בו התגברות והשחתה וטוב והצלה וזה כלו היה לי לישועה וזה כי הטוב שהיה בזה הפועל להוליך ישראל בים בלא נזק אין ספק שהיה לישראל לישועה ומה שהיה בו מההשחתה למצרים היה ג"כ ליש' לישועה כי בו נשלמה להם ההצלה מיד מצרים ובו הוישרו להאמין בשם יתע' האמנה שלמה או יהיה וזמרת מענין כריתה ויהיה יה מורה על ההפלגה והחוזק כמו שלהבת יה והרצון בזה כי עוז וכריתה חזקה היה מה ששפע מהשם יתעלה להשחית המצרי' והוא בעינו היה לי לישועה וזה תכלית הפלא שהיה הפועל המשחית והכורת הוא בעינו מושיע עד שיהיה כורת למצרים ומושיע לישראל:
@39 **ואנוהו.** פרשו בו ואושיבנו בנוה ר"ל שאבנה לו מקדש תראה שכינתו בו. וקצת רז"ל פרשוהו מענין נוי ויופי. וזה לפי שה שאחשוב הנוה והמעונגה. גבר יהיר ולא ינוה ר"ל שאין בו מן הנוי והיופי דבר ועם כל זה הוא יהיר וגאה ויהיה הרצון בזה זה אלי ואתארהו בתארים אשר יהיה בהם מהנוי והיופי מה שאפשר כי כבר ימצא בפעולותו תכלית הנוי והיופי ואו יהיה הרצון באמרו ואנוהו והוא יותר נכון שאני אתארהו בתארים מורים על היות לו נוח ומשכן לדבר בלשון בני אדם ר"ל שאני אתרהו כאלו הוא כח בגוף כי אי אפשר לאדם לדבר בו בזולת זה האופן בדרך מפורסם לכל האנשים ולזה אמר ימינך יי' ושאר מה שדומה לזה וכאלו התנצל בזה על תארתו בכמו אלו התארי' :
@40 **איש מלחמה.** ר"ל אדון המלחמה. כי הוא לבדו יוכל להגיע הרע כאשר ירצה בכל עת אע"פ שלא היה נכון המקבל שיגיע לו רע מפאת הגרמי' השמימיים:
@40 **יי' שמו.** רצה בזה שזה המשפט הו' מתהפך וזה שהשם ית' הוא אדון המלחמה ומי שהוא אדון המלחמה יי' שמו ולה הוא מבואר שאין שם זולתו מי שיהיה אדון המלחמה:
@42 **במצולות.** הוא מעמקי הים:
@43 **נאדרי בכח.** היו"ד נוכפת וענינו אדר בכח והרצון ימינך יי' האל הנאדר בכח ימינך יי' תרעץ האויב ויהיה ההכפל בימינך יי' על צד הצחות כמו כי הנה אויביך וגו'. ורבים כמוהו או יהיה נאדר בכח שב אל הימין ויהיה ימין פעם זכר ופעם נקבה וכמוהו רוח גדולה וחזק ויהיה הרצון בזה שימין השם יתע' והוא הטוב המסודר ממנו בנמצאות על הכונה הראשונה הוא נאדר בכח כי בו יתכן שיניע הם יתע' רע עליו ר"ל למי שירצה מצד השגחתו באנשים הטובים הדבקים בו ואמנם אמר זה כי הרעות לא יבואו מהשם יתע' מצד עצמותם אבל יושפעו ממנו הטובות תמיד והשם יתע' יסבב בהשפעתו הטובו' שיגיע בהם רע לרשעים לא שיכוון אל הרע אבל יכוון אל הטוב והוא הצמלת החסידים מידם ומצד שהוא טוב מושפע זה הפועל מהשם יתעלה. ולזה אמר שימין יי' והוא מה שיושפע ממנו שהוא מכוון אל הכוונה הראשונה הוא נאדר בכח להגיע בו לרעים על הכונה השנית ואולם השמאל הוא מה שיושפע ממנו שהוא בלתי מכוון בעצמו אבל היה מציאותו מהכרח החמר כמו הפכת הארצו' והאש הנופל ומה שינהג מנהגם:
@45 **נערמו מים.** עמדו כמו ערמה גבוהה כי הרוח היה דוחה אותם תמיד כל הלילה ולא היה כח למים שיהיו נגרים אבל היו עומדים כמו נד:
@45 **קפאו תהומות.** הנה תהום הוא קרקעית הים ורצ' בזה שקרקעית הים קפא ונקרש באופן שלא היה בו טיט אבל היה בתכלית הנגוב והיובש באופן שיוכלו ישראל לעבור בו הנה התהום יאמר פעם על החלק מהארץ אשר היה בו עומק המים ופעם יאמר על מעמקי המים בעצמם כמו תהומות יכסיומו מפני היותם שוכנים בחלק ההוא מהארץ כמו שיקראו היושבים במקום מה בשם המקום ההוא כאלו תאמר שמצרים היה שם מקום ונקראו המצרים מצאים על היותם שוכנים במקום ההוא אמר וירא ישראל את מצרים מת על שפת הים:
@46 **תמלאמו נפשי.** הוא מענין כריתה כמו בלא יומו תמלא. התמלא בשוכות עורו וענינו שכבר תכרית אותם נפשי וזה שאני אריק חרבי ותורישמו ידי או יהיה מענין אסיפה כטעם מלאו ואמרו האספו ונבואה. והרצון בו תאספם נפשי אין מקום אחד שלא יוכלו לברוח כי הים יהיה להם מצד אחד ואני וחילי מהצד האחר:
@47 **נשפת ברוחך כסמו ים.** הנה זהו הרוח המקביל לרוח הקדים אשר השיב את מי הים סוף על המצרים:
@48 **מי כמוך באלים.** הם השכלים המניעים הגרמים השמימיים ואמנם אמר זה כי אין בהם מי שיהיה לו יחס וערך עם השם יתע' כמו שבארנו בה' ממ"י:
@48 **נאדר בקדש.** ר"ל שהוא יותר אדיר בקדושה והבדל מכל שאר הנבדלי':
@48 **נורא תהלות עושה פלא.** ר"ל שהוא נורא להללו כי לא יוכל אחר לספר תהלתו והוא עושה פלא ומשנה טבע הנמצאות וזה דבר לא יוכל עליו אחד ממניעי הגרמים השמימיים כי לא ישנו מנהגם:
@49 **נטית ימינך.** ר"ל כי בימינך נעצמו והוא מה שהשפעת מהטוב להשגיח ישראל בו סבבת שבלעה הארץ את המצרים:
@50 **נחית בעוזך אל נוה קדשך.** הוא עבר במקום עתיד והרצון בו שהשם יתע' ינהל ישראל בעוזו אל נוה קדשו והוא הר המוריה אשר היה בו בית המקדש או ירצה כזה שהשם יתע' נהל ישראל בעזו והוא מה שחדש מהמופתים החזקים אל נוה קדשו ר"ל שקרב אותם לעבודתו עד שהביא אותם אליו כמו שאמר ואשא אתכם על כנפי נשרים ואביא אתכם אלי:
@51 **ירגזון.** הוא מענין יראה וחתת כטעם שם רשעים חדלו רוגז. רגזו ואל תחטאו:
@53 **בגדול זרועך ידמו כאבן.** ר"ל מרוב יראתם ופחדם מגדול גבורתך ישובו כאבן דומם:
@54 **בהר נחלתך.** הוא הר המוריה אשר נבנה בו בית המקדש כי הוא המקום היותר מוכן אל שידבק בו השפע האלהי ולזה אמר שהוא מכון לשם יתעלה מקדש הוא מקדש בדגש הקו"ף לתפארת והיה ראוי להיות באות הדלת כמו ועשו לי מקדש:
@59 **ויסע משה.** יתכן ישראל היו מתעכבים שם בים סוף לראות אם יוציא הים להם דבר מחיל המצרי' אשר טבעו שם ולזה זכר שמשה הסיעם משם או אולי לרוב שמחתם היו רוצים להתעכב שם במקום אשר נעשה להם זה הפלא העצם וסבב השם יתע' שיסעו משם באמצעות עמוד ענן ההולך לפניהם יומם ועמוד האש לילה:
@59 **וילכו שלשת ימים במדבר ולא מצאו מים.** יתכן שהיו נושאים מים בכלליהם לשתות כי לא יוכלו לעמוד ג' ימים בלא שתיה:
@62 **ויצעק אל יי'.** זה לאות כי המופתים יתחדשו ע"י הנביא באמצעות התפלה כמו שזכרנו:
@62 **ויורהו יי' עץ.** אמרו רז"ל במכילתא שעץ מר היה והנה אמרו זה להורות שעל צד המופת שבו המים המרים מתוקים לא בדרך טבע וזה הוא האמת בעצמו ר"ל שה הענין זה על צד המופת ויורה על זה מה שאמר והיה אם שמוע תשמע בקול וגו'. כמו שנבאר והנראה לנו שלזה העץ היה מבא בהמתקת המים אלא שלא היה באופן שיוכל להגיע ממנו זה הפועל הנפלא ר"ל שימתיק כל מי המעין ההוא אבל אם היה שימתיק המים היה ממתיק מהם שעור מועט מאד וכזה מצא בענין דבלת התאנים שצוה ישעיהו למרוח על שחין חזקיהו. וזה כי דבלת התאנים יש לו מבא מה כבשול המורסות אבל לא יתכן שיגיע ממנו כמו זה הפועל שיחי השחין כשימרחו עליו דבלת התאנים וכן תמצא במה שצוה אלישע לנעמן שירחץ שבע פעמים במי הירדן וזה כי הרחיצה במים ימצא בה תועלת מה בענין הצרעת אבל לא ימצא בה כמו זה התועלת הנפלא ובכלל הנה כל המופתים שיעשה השם יתע' יחבר להם מהסבות מה שיהיה בו יותר מעט מהזרות אצל הטבע. וכבר בארנו הסבה בזה בו' ממ"י:
@62 **שם שם לו חק ומשפט.** בארו רז"ל ששם צוה להם השם יתע' ענין שבת ודינין הנזכרים בואלה המשפטים אמרו שבת ודינין במרה איפקוד. ולפי הפשט הנה נצטוו במשפטים ההם אחר ששמעו עשרת הדברים כי אז תמצא בסוף פרשת יתרו ויאמר יי' אל משה כה תאמר אל בני ישראל אתם ראיתם כי מן השמים דברי עמכם וזה היה בלי ספק אחר ששמעו עשרת הדברים כי אז דבר השם יתעלה עמהם מן השמים ואמר אחר זה ואלה המשפטים וגו'. וזה לאול כי כל הספור הזה הוא נמשך ולה יתבאר שהמשפים האלה נצטוו בהם אחר ששמעו עשרת הדברות והנה הרצון בזה לפי מה שאחשוב שהעם הנזכר שהלינו על משה שם לשם יתע' חוק ומשפט ר"ל שהם חשבו עליו שאין מדרכו שיגיע ממנו זולת הרעו' ושזה הוא חוק השם יתע' ומשפטו כמו שהיה מאמין פרעה באמרו ראו כי רעה נגד פניכם לפי מה שביארנו במה שקדם והנה הביאם להאמין זה כי הם ראו שכל הנפלאות שהגיעו מהשם יתע' היה בהם רע מה כאלו תאמר שקריעת ים סוף היתה כדי שיטבעו המצרים בים וכן הענין בכל המכות והנפלאו' שנתחדשו ממנו והנה עמוד האש והענן לא היה במציאותו טוב מורגש ולזה נסה זה העם השם יתעלה אם יוכל להשפיע להם טובות לא יהיה בהם רע לדבר והשפיע להם הש"י אז על ידו זה המפות שהיה בו טוב בזולת רע ואמר להם השם יתעלה על יד משה לא תיראו שיהיה מדרכי להגיע הרעות לבד מפני מה שהבאתי למצרים מן הרעות כי אם תשמעו בקול השם יתעלה ותעשו הישר בעיניו ותאזינו למצותיו ותשמרו כל חוקיו הנה לא אשים עליך כל המחלה אשר שמתי במצרים כי אין מדרכי להגיע הרעות כמו שחשבתם וזה כי אני יי' רופאך ר"ל שדרכי להסיר המחלה מהדבקי' בי לא שאביאה עליהם הלא תראו שרפאתי המי' המרי' והמתקתי אותם וזה לאות כי אין מדרכי להגיע הרעות לבד כמו שחשבתם. או יהיה הרצון באמרו שם שם לו חק ומשפט ששם במקום ההוא סדר השם יתע' לישר' חוק ומשפט רוצה לומר ששם הודיעם שהוא יסדר להם חקים ומשפטים יתנהגו בהם במה שאמר להם אם שמוע תשמע לקול יי' אלהיך וגו'.
@62 **ושם נסה** ישראל ורומם אותם על כל שאר האומות במה שיעד אותם שיתן להם מצות וחקים ינצלו מכל רע בשמרם אותם כל שכן שלא יהיה להם לירוא שיביא עליהם כמו הרעות לבד כמו שהיה אומר פרעה כי הוא יסיר הרע מהאנשים הדבקים בו והראיה על זה שכבר המתיק המים המרים ויהיה נסהו מענין רוממות וכן מה שאמר לבעבור נסות אתכם בא האלהים. וכן נסה עלינו אור פניך יי' או יהיה ושם נסהו מענין ניסיון והרצון בזה שהשם יתעלה נסה ישראל בזה המופת אם יאמין בו בדרך שילך בתורתו כמו שאמר בענין המן למען אנסנו הילך בתורתי אם לא. וזה כי כשיראו ענין אלו המופתי' הנפלאי' אשר לא היה בהם כי אם השפעת הטוב היה ראוי שיכנעו ללכת בדרכי השם יתע' והנה השמיעה בקול מצות הש' יתע' הוא שיקבלו עליהם לקיים דבריו:
@63 **והישר בעיניו תעשה.** שתקיים המצות אשר צוה לעשות אשר להם תועלת בעצמותם כמו השבת אבדה ואהבת הריעים והדומים להם:
@63 **והאזנת למצותיו.** ר"ל שתאזין למצותיו ותתבונן בהם ותקיימם והם מצות עשה ומצות לא תעשה אשר יחייבם העייון:
@63 **ושמרת כל חקיו.** הם מצות עשה ולא תעשה שאין טעם מבואר בענינם וענין השמירה הזאת הוא לזכור עניינם ולקיימם ושלא לעבוד עליהם:
@64 **ושם שתים עשרה עינות מים ושבעים תמרים.** להעיר כי השם יתע' היה מנהלם במקומות היותר נאותים אל שימצא להם שם ההכרחי להם:
@67 **בשבתנו על סיר הבשר.** ר"ל שהיה הבשר נמצא להם שם בשפע:
@68 **הנני ממטיר לכם לחם מן השמים.** ראוי שתדע שזה המופת היה נפלא מאד כי לא יתכן שיתהוה ע"ד הטבע דבר מזה בעת מהעתים כי לא יתהוה מאלו האדים העולים באויר דבר יתכן שיהיה מזון וזה מבואר במעט עיון למי שעיין בטבעיות והנה עכ"פ יתכן שיהיה מערוב היסודות והמזג שמה שיהיה טבעו כטבע זה המן אשר ירד להם מן השמים שאם לא היה הענין כן יהיה מציאות המן נמנע מצד עצמותו ומה שזה דרכו לא יתחדש ע"ד מופת כמו שלא יתחדש ע"ד מופת מציאות מרובע יהיה קטרו שוה לצלעו. וכבר בארנו זה בו' ממ"י ושם בארנו זה הענין הוא דעת תורתנו ושהוא מחוייב מצד העיון והנה היה התהוות המן בזולת סבותיו באופן התהוות מהמטה נחש ר"ל שאין התהוות המן ומציאותו דבר נמנע מצד עצמותו כמו שאין מציאות הנחש נמנע מצד עצמותו ואמנם היה נמנע מצד הטבע שיהיה המן מאלו האדים או מהאויר ושיהיה הנחש מהמטה:
@69 **והיה ביום הששי.** ר"ל שיאפו ממנו ביום הששי מה שיצטרך לכבוד השבת כמו שבאר אחר זה כי בשבת לא יוכלו לאפו' ולבשל כי הם מהמלאכו' האסורות לעשות בשבת כמו שנתבאר בה המקו' ושיתבאר במה שיבא ורז"ל ביארו מזה שהוא אסור להשתמש בשבת במה שלא היה מוכן לצורך שבת מערב שבת כמו גרוגרות וצמוקים בעת התיבשם לשמש שאינם ראויות מצד עצמתם אבל הדברים ראוים בעצמם אע"פ שהם בלתי מוכנים מפני שהם עומדים לסחורה הנה הם מוכנים אצל שבת כי לגודל מעלת השבת ישים האדם כל הדברים אשר בידו מוכנים אצלו וכן למדנו ענין ההכנה ליום טוב מזה המקום אלא שיש הבדל בדיני המוקצה בין שבת לי"ט כי י"ט יהיה מוקצה מה שיהיה לסחורה אע"פ שהוא ראוי בעצמותו וכן יהיה מוקצה הב"ח העומד לגדל התרנגולת לביצתה ורחל לגזתה כי אין מעלת י"ט אצל האנשים כמעלת שבת ולזה לא יהיו אצלו כל הדברים הראוים בעצמם מוכנים כמו הענין בשבת. וכבר נסתעפו מזה השרש דינים רבים במסכת י"ט ובמסכת שבת ובמקומות זולתם מהתלמוד:
@69 **והיה משנה על אשר ילקטו יום יום.** כדי שיספיק להם לשני ימים ערב וידעתם כי אני יי' וגו' ר"ל שכבר יתבאר לכם עוצם כחו וגבורתו לעשות כל אשר ירצה וזה שכל מה ששאלתם ממנו יתן לכם עד שכבר יביא לכם בשר לאכול בזה המדבר בזה היום בעינו קודם שיעבור הערב ובבקר תראו כבוד יי' במה שישפע ממנו לכם לחם לאכול בזה האופן הנפלא לפי שהוא שמע תלונותכם:
@72 **אשר אתם מליני' עליו.** כי לא עלי ועל אהרן תלונותיכם במה שאמרתם לנו כי הוצאתם אותנו אל המדבר הזה להמית כל הקהל הזה ברעב כי אם מהש' יתעלה כי מאתו נהיה כל אשר עשינו:
@74 **והנה כבוד השם נראה בענן.** זה היה על צד המופת. רוצה לומר שהיו מכירים ישראל בבא הנבואה וזה היה בהרבה מנבואותיו לפי מה שהתבאר מדברי התורה וזה היה כלו להביא ישראל שיאמינו בענין הנבואה כדי שיקבלו התורה קבלה שלמה שלא ישאר להם ספק בשהיא מהשם יתעלה:
@76 **בין הערבים תאכלו בשר.** ר"ל בזמן אשר בין הערבים והרצון בזה שקודם שתסור היום לגמרי יאכלו בשר:
@77 **ותעל השליו.** הוא מין ממיני העופות ואולי העלה אותם השם יתעלה מן הים כמו שכתב החכם א"ע שכבת הטל הו' הטל שיורד בבקר והנה אמר שכבת הטל לפי שהוא נעשה מאיד חלוש לא ירדו ממנו טיפים אבל יתלחלח מהקרירות אשר בסוף הלילה וימצא הלחות בפועל על הארץ:
@78 **ותעל שכבת הטל.** ר"ל שנפסקה ירידת הטל כמו שפירש החכם אבן עזרא. והרצון בזה שהטל יהיה יורד ראשונה ואחר שירד הטל ירד המן עליו כמו שכתוב ורדת הטל על המחנה וגו':
@78 **דק מחוספס.** פירש החכם אבן עזרא שהיה דק ועגול גם נכון הוא מה שפירש המתרגם רצוני שהוא היה כדמיון זרע דק קלף ר"ל שהוסרה קליפתו כי הוא היה לבן כזרע גד כמו שספר אחר זה:
@80 **עומר לגלגולת.** פירש אחר זה כי העומר הוא עשירית האיפה והאיפה היא מדה שעורה שלש סאין והנה הסאה היא ו' קבין והקב היא ארבעה לוגין ולזה תהיה מדת העומר שבעה לוגין וחמישית לוג:
@81 **ויעשו כן בני ישראל.** ללקט עומר לגלגלת כאשר צוה להם משה:
@81 **וילקטו.** מי שהיו לו בני בית מרובין ומי שהיו בני ביתו מועטים לפי האומד באופן שיהיה בו עומר לגולגולת וכאשר מדדו מה שלקטו מצאו שהמרב' לא העדיף מעומר לגלגלת והממעיט לא החסיר וזה היה דבר פלא כי הרצון היה מהשם יתעלה שיהיה להם לחם חקם לא פחו' ולא יתר ולזה סבב שימצאו הענין בזה האופן:
@83 **איש אל יותר ממנו עד בקר.** הנה צוה השם יתעלה להם לסבות האחת כי זה השיעור הוא ראוי למאכל אדם ר"ל עומד לגולגולת ולא יוכלו להותיר ממנו שלא יזוק גופם. והשנית כי ההשתדלות להותיר ממנו עד בקר היה מורה על מיעוט האמנה בשם יתעלה לא יבטח המותיר ממנו עד בקר שירד המן בבקר שאם היה בוטח בזה לא היה משתדל להותיר מהמן עד הבקר. ולזאת הסבה כעס משה על האנשים שהותירו ממנו עד בקר וסבב השם יתעלה שלא יועיל להם כי כבר באש והיתה בו רמה:
@85 **וחם השמש ונמס.** סבב זה השם יתעלה כדי שילקטוהו בזריזות בבקר השכם קודם שיביאו הרוחות עליו עפר ולהקנותם תכונת הזריזות ויהי ביום הששי לקטו לחם משנה. יתכן שהיה זה על דרך פלא כי לא מצאנו שצוה משה להם שילקטו ביום הששי לחם משנה והנה הם היו לוקטים לפי האומד עומר לגלגולת וכאשר מדדו בעומ' מצאו שכבר לקטו שני העומר לאחד ולזה באו כל נשיאי העדה להגיד למשה הדבר הזה לאמת מה זה ועל מה זה. ואפשר כמו שכתב החכם אבן עזרא שאמר להם משה שילקטו ביום הששי לחם משנה ואם לא נזכר ובאו נשיאי העדה לדעת מה יעשו ממנו. והנה הביאור הראשון נכון הוא יותר שאם היה כפירושו למה זה לא שאלו נשיאי העדה מה יעשו מזה הלחם המשנה ואיך יאכלוהו כאשר צוה אותם שילקטו ביום הששי לחם משנה והנה סבב השם יתעלה שידעו כי ביום השביעי הוא שבת בזה האופן קודם שיצוה אותם משה בענין השבת כדי שיאמינו יותר בענין השבת כי הם ראו כי ביום הששי ירד להם משנה ולא ירד ביום השביעי וזה לאות כי היום הזה נבדל בענינו משאר ימי השבוע ושהוא בלתי ראוי שתעשה בו המלאכה ולזה אמר להם משה זה אשר ראיתם שירד ביום הששי לחם משנה:
@87 **הוא אשר דבר יי' שבת שבתון שבת קודש ליי' מחר.** ר"ל שהוא מחוייב שישבתו בו מכל מלאכה ואין ראוי להתעסק בו רק בעבודת השם יתעלה ולזה אפו ביום הששי מה שיצטרך לאפות לצורך השבת ובשלו הצורך לבשל והעודף הניחו למשמרת עד הבקר לאכלו בשבת והניחוהו עד הבקר ולא הבאיש ורמה לא היתה בו כי מאת השם נהיה שיניחו אותו למשמרת ולזה לא קרה בו מה שקרה במה שהותירו עד בקר בשאר ימי השבוע כי הוא הבאיש והיתה בו רמה ויתכן שהודיעו למשה שלא הבאיש ולא היתה בו רמה ואמר להם משה אז שיאכלוהו ביום שבת ולא יצאו ללקוט כי לא ימצאו וכל זה היה להוסיף להם האמנה בענין השבת:
@92 **לשמור מצותי ותורותי.** רוצה לומר במצותי מה שעברו על דבר השם להותיר מהמן עד הבקר ולצאת ביום השבת ללקוט ואלו המצות הם בעינם התורות שזכר כי צוה הש יתע' אלו הנימוסים בעניין המן והשבת ובזה האופן קרא התורה נימוס אשר צוה השם יתעלה שיעשו בו דבר אחד מהדברי אמר זאת תורת החטאת זאת תורת האשם ואפשר עוד שקרא אלו המצות תורות לפי שאין הכונה בהם עניין אלו המצוות בעצמותו אבל הם מכונות להורות על דברים אחרים כאלו תאמר שמצות השבת היא להורות על חדוש הועלם או על יציאת מצרים גם כן כמו שזכרה התורה זה בפרשת וישמע יתרו ובפרשת ואתחנן ומה שצוה השם יתעלה שלא להותיר מהמן עד הבקר היה להורות כי ראוי לאדם יסתפק בלחם חקו ולא יפנה לרבוי אסיפת הקנינים שימנעוהו במה השתדלות בשלמות הנפש עם שכבר היה זה להרגילם שיאמינו בשם יתעלה שכבר ירד המן להם בבקר בבקר:
@93 **שבו איש תחתיו וגו'.** ולזא' הסבה נתחייב המקושש סקילה כמו שנתבאר בתורה ומזה המקום יתבאר שההכנסה מרשות הרבים לרשות היחיד היא אסורה בשבת וכבר נבאר זה בג"ה מצד אחר בפרשת יתרו והנה הוציאו רז"ל ענין. התחומין של תורה מזה המקום בראשון מעירובין אלא שעכ"פ פשט הכתוב הוא כמו שבארנו וענין התחומין יתבאר לנו ממקום אחד כמו שנבאר בפרשת יתרו ואלו היתה זאת האזהרה למנוע היציאה מהמחנה הנה יתחייבו האנשים אשר בקצה המחנה בלכתם פסיעה אחת שיצאו חוץ למחנה וזה דבר בלתי ראוי שנאמינהו כי המשקושש יצא חוץ למחנה לפי מה שיראה ממה שאמר וימצאו איש מקושש עצים לא היה חייב אלא מפני שהיה מקושש ולזה לא נענשו המוצאים אותו ולא גונו על צאתם מהמחנה ואולם הביאו רז"ל זה הפסוק לאסמכתא לבד כמנהגם ברבים מביאורי דיני המצות ואפשר שנאמר שהרצון בזה שישבו תחתיהם מי שלקטו דבר חוץ למחנה כי אין להם להוציאו חוץ מהמקום ההוא שהוא תחתיו כי אי אפשר שנאמר שיצוה אותם משה שישבו בשבת במקומם ולא יצאו משם שאם היה הדבר כן היו מוצאי המקושש חייבים ולזה הוא מבואר שזה המאמר היה למי שילקט דבר בשבת בחוץ ואמר אחר זה אלי יצא איש ממקומו להזהיר אפילו על היציאה בזולת לקיטה והנה היציאה מהמקום לפי מה שימצא מהמדינות לא יהיה בפחות משיעור המדינה כי עד כמו שיעור המדינה לכל הצדדים ימשכו לכל הפחות שדות העיר וכרמיה ויעריה ולפי שמחנה ישראל היה אז ג' פרסאות לפי מה ששערו לפי מנין האהלים שהיו שם הנה היתה זאת האזהרה שלא יצאו שלש פרסאות חוץ למחנה כי לא היה הרצון בזה שלא יצא כלל מן המחנה כמו שביארנו. ולזה תהיה הכונה בו שלא יצאו ממה שהוא ראוי שיהיה נכלל במקות המחנה ולפי שהם היו במדבר שלא היתה שם שדות וכרמים הנה יהיה זה השיעור כולל בכל מדינה היתה גדולה או קטנה ואע"פ שאין גבוליה מגיע לכמו זה השיעור אז ירצה בזה באמרו שבו איש תחתיו שמי שיצא חוץ לשלש פרסאות ישב במקומו שלא יהיה לו רשות לשוב אל המחנה ולא יוכל ללכת יותר מארבע אמות ובזה חטאו היוצאים מהמחנה' ללקט כי הם לא לקטו דבר עם שהיה בזה הפועל ממיעוט האמונה בשם יתע' מה שלא יעלם:
@95 **זרע גד.** אחשב שהוא אחד מהזרעים הקטנים הלבנים ודמהו לו מצד הלובן כאלו יאמר שהוא לבן כזרע גד ולפי זה הפירוש אפשר שיהיה מאמר לאה בא גד להיותו הבן ההוא לבן ולזה המשילה אותו לגד וקראו גד או ירצה בזה שהוא כזרע גד כדמיונו וכדמותו והיה גם כן לבן:
@95 **וטעמו כצפיחית בדבש.** אמר זה להורות על הפלגת שבח המן שהוא היה לתכלית הערבות בטעמו. והיה טוב למראה:
@97 **לפני יי'.** ר"ל לפני ארון העדות והוא בקדש הקדשים כמו שיתבאר במה שיבא והנה היה זה המן קיים לדורות ובלתי נפסד על צד הפלא ר"ל שכבר נתן לו השם יתע' טבע אז על יד משה נביאו על שיהיה בלתי נפסד עם היותו קל ההפסד בעצמותו עד שהיה נמס הנשאר מהמן חוץ מהמחנה בחום השמש כמו שקדם:
@102 **מה תנסון.** יתכן שהיו אומרים זה על צד הנסיון כי כבר היו מהם מים לשתות שהביאו מאלים אך רצו לנסות אם יוכל משה לתת להם שם מים וכזה יודע להם כי מהשם היה כל אשר הוא עושה ואם לא יוכל על זה יאמרו כי אין ה' בקרבם כמו שהיה אומר שמה וממה שנתחדש מהנפלאות היה על דרך המקרה וזהו מה שאמר אחר זה ועל נסותם את יי' לאמר היש יי' בקרבנו אם אין וזה שאם היה השם בקרבם היה יכול לתת להם מים בלי ספק כי הוא שליט בכל והנה החלק מהעם שהריב עם משה ונסה השם יתעלה הוא זולת החלק שצמא למים והנה החלק מהעם שצמא למים לא שאלו המים כהוגן אבל אמרו דבריהם בדרך התרעומת ולזה אמר משה בהתפללו לשם יתע' שיתן להם מים. עוד מעט וסקלוני:
@106 **הנני עומד לפניך שם על הצור.** הוא לדבר כלשון בני אדם והרצון בו שכבר ישפע לך ממני שם זה המופת שכאשר תכה בצור יצאו ממנו מים שיספיקו אל שישתו מהם העם או ירצה בזה שאתה תשתדל להדבק בי כי שם בדרך שאהיה עומד לניך ואז יתחדש זה המופת על ידך מפני דבקותך בו וידמה לפי מה שהכינו רז"ל במכילתא שישראל אמרו למשה איה כוחך וגבורתך להביא באמצעות המטה כל מה שתרצה כמו שעשית במצרים תנו לנו מים באמצעות המטה אבל בלי ספק לא תוכל על זה כי לא נעשה באמצעות המטה מופת אלא לרע לפי שאין מדרך האלוה ההו' אשר חדש אלו המכות לעשות כי אם רע ואלו יעשה המופתים ההם על יד השם יתעלה הנה בלי ספק יוכל לתת לנו מים באמצעו' המטה כי הטובות שופעות ממנו באמצעו' בנמצאות בתכלית מה שאפשר להם מהטוב והשלמות ומפני זה רצו לנסות בזה הענין אם יש יי' בקרבם במה שחודש מהנפלאות באמצעות המטה או היו הנפלאות ההם מאלוה אחר דרכו שיגיע ממנו רעות לבד ולזה צוה השם יתעלה שיעשה זה המופת אשר היה לטיוב באמצעות המטה וזה פירו' נאה מאד בזה הענין:
@109 **בחר לנו אנשים.** ר"ל אנשי מדות שהיו ראוים למלחמה או יהיה הרצון בה אנשי מעלה כדי שיהיו יותר ראוים שיעשה להם נס אנכי נצב על ראש הגבעה. הנה עשה משה כן כדי שיראוהו ישראל ויתבאר להם כי בהרימו ידיו יגבר ישר' ובהניחו ידיו יגבר עמלק ולזאת הסבה לקח המטה בידו כדי שיתברר להם כי השם יתעלה יחדש להם זה המופת באמצעות המטה:
@112 **וידי משה כבדים.** יתכן שהיה גדול הגוף והיא עם זה זקן והנה אלו הם שתי סבות לתת לו כובד באיבריו וזה מבואר למי שעיין בטבעיות עיון שלם ולזה גם כן לא יכול משה לעמוד תמיד כל מה שהתמידה המלחמה ולפי שהיתה הכונה שתהיה במקום גבוה כדי שיראוהו ישראל לקחו אבן והושיבוהו עליה בדרך שיגבה מקומו ולהיות ידיו כבדים תמכו אהרן וחור בידיו מזה אחד ומזה אחד בדרך שהתמיד להגביה ידיו מעת שתמכו בידיו אהרן וחור מזה אחד ומזה אחד עד בא השמש:
@113 **את עמלק ואת עמו.** יתכן שהביא עם אחד עמו להלחם בישראל:
@114 **כתוב זאת זכרון בספ'.** יתכן שכתב זה בספר מה היה ידוע אצלם והוא ספר הזכרונות או ספר מלחמות יי'. כמו שכתב החכם אבן עזרא או ר"ל שיצוה לישראל לזכור את אשר עשה עמלק ולמחות את שמם כמו שבא הצווי בזה בתורה ולזה כתב זה הספור בתורה כי השם יתעלה הוא אשר יתן כח לישראל למחות את עמלק המחות נפלא ומוחלט ולזה זכר זה הנס שעשה השם יתע' לישראל ולזכר בנה משה מזבח על ראש הגבעה וקרא שמו יי' ניסי. והרצון בו שהוא נלחם בעבורי ולא אצטרך לנס הרים במלחמה לשמור שלא תהיה חרב איש באחיו:
@116 **ויאמר כי יד על כס יה.** קבלתי בפירוש זה הפסוק מהרב אדוני אבי שהוא אמר כי היד שהוא על הכסא יהיה ממנה מלחמה ליי' בעמלק מדור דור מישראל שיהיו נלחמים בעמלק כי יד יי' תהיה אתם תמיד לעזרם. והנה הכסא הוא השמים כטעם השמים כסאי והנה השם יתעלה הוא מושל על מה שיסודר מהגרמים השמימיים להפך הסדור ההוא כאשר היה מסודר ממנו רע מה שאוהביו הדבקים בו ובזה הכח אשר לו על הכסא היה נלחם בעמלק כי לפי המערכת היה עמלק מנצח ישראל לולי עזר השם יתעלה וכן תמצא בימי המן כי לולי עזר השם יתעלה היו ישראל נופלין ביד העמלקים והנה זה הפירוש הוא נכון מאד ואפשר שנאמר לפי הפירוש הזה כי זאת המלחמה היתה מן היד אשר על כס יה ולזה קרא שם זה זה המזבח יי' ניסי. ובזה האופן תהיה המלחמה ליי' בעמלק מדור דור מישראל הנלחמים עמו כי תמיד היה עמלק מנצח לפי המערכת לולי עזר הש' יתעלה:

@38 **אז ישיר משה וגו' עד ויסע משה את ישראל:**
@38 **ביאור דברי הפרשה והשירה:**
@38 **אז** שר משה וזאת השירה ולמדוה ממנו ישראל ושוררות יחד. ויאמרו לאמר הנה ראוי שאשיר ואשבח השם יתע' בהמשלים ודמיונים כי גאה גאה מאד מלספר שבחיו ועצמותו וכאלו אמר זה להתנצל על אשר יתארהו באלו התארים ידבר בהם בלשון בני אדם הנה ירה בים סוס ורוכבו במהירות נפלא עוז השם יתע' להגיע הע כאשר ירצה והפלגת טובו וחסדו וזה הפועל בעינו היה לי לישועה או יהיה הרצון בזה כי הש' יתע' גאה מאד ורחקה מדרגתו מאד מאלו הענינים השפלים רוחק נפלא ועם כל זה הגיע מיתרון השגחתו שירה בים סוף סוס ורוכבו הנה זה המקרה היה עוז וכריתה חזקה ועם כל זה היה לי לישועה כי בו נשלמה ההצלה לישראל מיד המצרים עם שהרע בעינו שהגיע למצרים היה לישראל לישועה כי זה הפלא העצום שראו בזאת המכה הביאם להאמין בבשם יתעלה אמונה שלמה או ירצה בזה שהשם יתע' הוא עוז וטוב ר"ל שכבר יגיע ממנו לנמצאות פעם עוז ופעם טוב ור"ל בעז הרע אשר יתקוף האדם וינצחהו וזה שכבר יגיע ממנו רע מה לנמצאות במקרה אבל היה לי לישועה תמיד ר"ל שמיתרון השגחתו בי יצילני מהרעות הנכונות לבא עלי הנה זה הוא אלי ומנהיגי ולזה לא יזיקני הרע הנכון לבא עלי מפאת הגרמים השמימיים ואתאר אותו בתארים מורים על היותו כח בגוף ואם אין הענין כן כדי לפרסם שבחיו או ירצה בזה שכבר אתאר אותו בתארי מורים על תכלית הנוי והיופי וזה בעינו היה מנהיג אבותי ומשגיח בם וארומם אותו בתארי על כל שאר הנמצאות כי אין בהם מי שיהיה מהיקש ויחס בינו וביניהם הנה השם יתעלה הוא אדון המלחמה כי הוא יביא תמיד הרע על אויביו כאשר ירצה ומי שהוא אדון המלחמה יי' שמו כי אין שם זולתו מי שיהיה שליט בכל אשר ירצה הנה הוא סבב בעומק מחשבותיו להביא בים מרכבות פרעה וחילו במהירות נפלא כי הוא סבב שישובו ישראל לחנות בין מגדול ובין הים בדרך שיחשב פרעה כי הם נבוכים בארץ ויחזק לבו לרדוף אחריהם וסבב גם כן בזה האופן שטבעו בים סוף מבחר גבורי פרעה כדי שייראו הנשארים מרדוף עוד אחרי בני ישראל הנה תהומות הים כסו אותם ירדו במצולות הים כמו אבן שירד שם במהירות נפלא ליתרון כבדותו וכזה אמר שבמהירות נפלא סבב השם יתע' שירדו במצולות הנה ימינך השם יתע' והוא מה שיושפע ממך מהטובות הוא אדיר בכח להביא באמצעיתו רע נפלא לאויבך וזה הוא תכלית הפלא ר"ל שיגיעו מפועל הטובות מהצד אשר הוא פועל הטובות כמו אלו הרעות הנפלאות כי השם יתע' לא יפעל הרע בזולת זה האופן הנה ברוב גאונך ורוממותך מענין הרעות ר"ל שאין מדרכך לפעול אותם מצד מה שהם רעות בו בעינו תגיע הרעה לקמיך עד שתהרוס אותם ותשלח חרונך ויאכלם כקש שיאכלהו האש במהירות נפלא וזה הוא ענין נפלא כמו שקדם וכבר ביארנו באי זה אופן יגיעו מהשם יתע' אלו הרעות בספר מלחמות יי' אמר על דרך משל הנה ברוח אשר יצא מאפך נתקבצו מי הים לצד אחד ונעשו כמו ערמה והנה אמר זה מפני כי מהאף לא יוכל האדם להוציא רוח גדול אבל יוציא הרוח הגדול מפיו וכאלו אמ' שבמעט מכחו השיב זה הרוח הנפלא שדחה מי הים לצד אחד כל הלילה והציבם כמו נד ונגב קרקעית הים אשר הלכו בו באופן שלא היה בו טיט אמר פרעה ארדוף ישראל ואשיג אותם כי הם חונים על הים ולא יוכלו לברוח אחלק שללם לעמי תאספם נפשי אל מקום אחד סמוך לים ולא ימלט אחד מהם הנה כשאשיגם בכמו זה האופן אריך חרבי ואקח כל קניניהם לא ישאר דבר הנה נשפתה ברוחך שחדשת והשב'' עליהם מי הים וסבבת שנהפך אליהם הרע אשר יזמו לעשות במהירות נפלא עד שצללו במים אדירים כמו שיצלול העופרת במהירות נפלא ליתרון כבדותו. מי כמוך בשאר השכלים הנפרדים מי כמוך שיהיה נאדר בקודש ר"ל ששאר הנבדלים הם קדושים אך הוא יתע' נאדר בקדש עד שאין יחס בינו וביניהם והוא נורא תהלות. כי כל אחד מהנמצאות יירא מלספר תהלותיו כי לא יוכל והוא עושה פלא לשנות טבע המציאות כאשר ירצה ואע"פ שכבר יעשה זה באמצעות השכל הפועל כמו שביארנו בששי ממ"י הנה השכל הפועל יעשה זה מצד השפע השופע עליו מהשם יתעלה כמו שהתבאר שם הנה נטית ימינך להטיב לישראל ובפועל ההוא בעינו סבבת שבלעה הארץ המצרים ואמנם אמר זה לפי מה שאחשוב כי כבר נהפכה הארץ אשר היו שם פרעה וחילו לטיט כששב עליהם מי הים וטבעו בטיט ההוא או טבעו בטיט אשר היה במצולות הים כשדחו המים אותם שם הנה זה תכלית הפלא כי בחסדך והוא הטוב השופע ממך נחית עם זו וגאלת אותם מיד המצרים ובעוזך וביד החזקה והם המכות הנפלאות הבאת על המצרים הגיע לישראל מהטוב יותר מה שהגיע להם בחסדך וזה כי נהלת אותם אל נוה קדשך וקרבת אותם לעבודתך כי בזה הכירו וידעו כי אתה יי' לעוצם הנפלאות ההם עד שזאת האמונה שקנו זה היתה כלי להנחילם הארץ בעבור מה שהוישרו בו לעבודת השם יתע' ובהיות הענין כן הנה הגיע להם מחסדך טוב גופיי ומעוזך הגיע לה' טוב נפשיי אשר הוא נפלא מהטוב הגופיי לאין קץ עם שממנו גם כן תשלם להם ירושת הארץ שהוא טוב גופיי והוא גם כן טוב נפשיי באופן מה לרוב הכנתה אל שידבק בה השפע האלהי והנה מצד אחר גם כן היה זה הענין כלי להנחיל ישראל את הארץ מצד האימה והפחד שהפיל על האומות ההם וזה שכבר שמעו רבים עמים אלו הנפלאות ופחדו וייראו מאד חיל אחז יושבי פלשת לפחדם שיבואו ישראל להלחם עמהם שדי אדום ואלופיו נבהלו ושרי מואב וגבוריו אחז אותם רעד ורתת נמוגו כל יושבי כנען לפחדם מהם תפול עליהם אימתה ופחד בגדול זרועך וגבורתך הנפלאה ימות לבם עד שיהיה כאבן דומם כמו שתמצא בספר יהושע שאמרה רחב למרגלים ידעתי כי נתן יי' לכם את הארץ וכל נפלה אימתכם עלינו וכי נמוגו כל יושבי הארץ מפניכם כי שמענו את אשר הוביש יי' את מי ים סוף מפניכם וגו'. ונשמע וימס לבבינו ולא קמה עוד רוח באיש מפניכם וזאת האימ' והפחד תהיה לאומות האלו עד שיעבור עמך אשר קנית את הירדן ותביא אותם ותטעם בהר נחלתך והוא הר המוריה שהיה בו בית המקדש הוא מכרון אשר פעלת לשבתך ר"ל שבו תמצא תכלית ההכנה אל שידבק בו השפע האלהי והוא המקדש אשר כוננו ידיך להשרות שכינתך בו והנה זכר הר המוריה לבד מבין ארץ ישראל כי הוא המקום הנבחר שבארץ ישראל כאלו אליו היתה הכונה בירושת הארץ הנה הש' יתע' יתפרסם מענינו לאנשים לעולם ועד שהוא שליט על הנמצאות ומולך עליהם לעשות מהם כחפצו וזה שכבר הגיע מתכלית גבורתו שסבב להביא סוס פרעה ברכבו ובפרשיו בים והשיב עליהם מי הים בעת שהיו בני ישראל הולכים ביבשה בתוך הים והנה לקחה מרי' הנביאה התוף בידה ויצאו כל הנשים אחריה בתופים ובמחולות ואמרה להם מרים שירו ליי' כי גאה גאה סוס ורוכבו רמה בים ואולם התועלו' המגיעו' מזאת השירה הם י':
@59 **ויסע משה וגו' עד ויבא עמלק:**
@59 **ביאור דברי הפרשה:**
@108 **ויבא עמלק עד סוף הפרשה.**
@108 **ביאור דברי הספור:**
@108 יש לשאול בזאת הפרשה שאלו' קשות. האחת מה ראה עמלק לעורר מלחמה לעם רב כזה ואי לא פחד מהנפלאות שעשה השם יתע' לישראל בים סוף ובמצרים שהיו מפורסמות לכל האומות כמו שהתבאר בזאת הפרשה. והשנית למה היתה המלחמה על ידי יהושע ולא על ידי משה רבינו. והשלישית אי זה דבר הכריח שלא ישלים ההתגברות לישראל כי אם בעת שהיה משה מרים ידו עד שהוכרחו אהרן וחור לתמוך בידיו עד בא השמש ולא מצאנו שהוצרך משה לכמו זה הפועל בשאר הנפלאות הקודמות עם שהוא מבואר בנפשו שלא היה רושם בהרמה ידי משה לנצח עמלק כמו שאמרו ז"ל בשני ממגלה. והרביעית מדוע בחר משה להיות במקום גבוה בעת הרימו ידיו להתפלל לשם יתעלה בעד ישראל וזה כי אין לאומר שיאמר שהיה זה בעבור היות המקום ההוא נבחר אל שידבק בו השפע האלהי כי הוא היה באופן מהדבקות בשם יתעלה עד שכבר נאמר לו מה תזעק אלי כ"ש שלא יצטרך אל התמדת התפלה ואל שיבחר המקום היותר נבחר להגיע אליו השפע האלהי וסוף הדברים כי זה הספור כולו הוא חזק הספקות מאד ונאמד כי עמלק מפני היותו מזרע עשו והיה ידוע להם ענין הברכו' שבירך יצחק יעקב שהושם בהם זרע עשו עבד לזרע יעקב וענין מה שאמר יצחק לעשו ברכו אותו שעל חרבו יחיה והיה כאשר תהיה לו מצד המערכת הממשלה יפרק זרע יעקב מעל צוארו הנה התחכם עמלק להלחם על ישראל בעת שהיה ראוי שינצח מצד המערכת עם שנפש ישראל היתה אז שפלה ולא היו מלומדי לחמה והיו במדבר בזולת לחם ומזון לפי מחשבתו והיו עיפים ויגעים וזרע עשו היה גם כן מצליח בענין החרב והמלחמה כמו שברכו יצחק קודם שתגיע הצלחת ישראל באופן שישים זרע עשו לעבד לו והנה התחברה גם כן לזה סבה אחרת ואם לא כיון אליה עמלק והיא שישראל לא היו יראים מהשם יתעלה באון שהיו ראוים שיעשה להם זה הנס כמו שאמר ואתה עיף ויגע ולא ירא אלהים ויורה על זה מה שהריבו ונסו השם בזה המקום ולזה היו ישראל מפני זה כלם בתכלית הסכנה ולהראות לישראל כי מאת השם יתעלה היה להם עזר להצילם מיד עמלק וזרועם לא הושיעה למו כדי שתהיה להם אמונה שלמה בהשם יתע' ויכנעו לקבל התורה רצה משה שתעשה המלחמה על יד יהושע ועמד הוא במקום גבוה שיראוהו ישר' ויתבאר להם כי בעת הרים משה ידיו היו מנוצחים ובהניחו ידיו היו מנצחים והיה זה על צד המופת להביא ישראל להאמין כי העזר היה להם בזאת המלחמה מהשם יתעלה ולזה כשלא היה יכול משה לעמוד שמו אבן תחיו באופן שיהיה במקום גבוה שיראוהו ויראו ענין הרמת ידיו והנה באר בסוף הענין כי הרמת ידי משה היתה להורות שהיד אשר היא על השמים והיא יד השם יתעלה היא היתה הנלחמת בעמלק וזהו מה שאמ' ז"ל במכילתא וכי ידיו של משה מתגברות ישראל או שוברות עמלק אלא כל זמן שהיה מגביה ידו כלפי מעלה היו ישראל מסתכלים בו ומאמינים במי שפקד משה לעשות כן והקב"ה עושה להם נסים. ובכאן הותרו אלו הספקות כלם ולפי שכבר נתחכם עמלק להכרית ישראל רצה השם יתעלה שישולם לו מדה כנגד מדה עם שבזה ינצלו ישראל מידו כי הוא היה בהרבה מהעתים מתגבר על ישראל מצד המערכת ואם לא ישתדלו ישראל למחות זכרו בהיות לאל ידם יהיו בסכנה עצומה בעת שיהיו בלתי ראוים שתדבק בהם ההשגחת האלהית והיה עמלק מתגבר עליהם מצד המערכת והנה השם יתברך נתן זאת התורה השלימה לישראל להצילם מכל רע נפשיי או גופיי לפי מה שאפשר ולזה חוה לנו לזכור מה שעשה עמלק למחות זכרו כשנוכל על זה. ואולם התועלת המגיע מדברי זה הספור הוא להודיע אופן השגחת ה' בדבקים בו ואיך התחכם השם יתברך בכל הפנים שאפשר להעתיק ישראל אל האמונה בו כדי שיוכנו לקבול התורה אשר אליו היתה הכונה מתחילת הענין. ואמנם כונה התורה לתכלית נאות בהיו' מכוון שנפול לסוף בסבת היותנו ראויים לעונש גדול מזה ונהיה גולים בין זרע עשו אשר הם מושלים ותקיפים והם הגבורים אשר מעולם כדי שלא ימס לבנו ותסור תקותנו מהשם יתע' ספרה לנו ענין עמלק בזה הספור למען נחזק לבנו ונאמין אל כל היעודים שהבטיחו נביאנו ע"ה על ענין הגאולה פן יחיתנו ח"ו לפני בני עולה ונקוה לאלהינו כי כבראשונה ישיבנו עם מרום הרים יושיבנו יראו עינינו בבניין אלהינו אמן ובמהרה בימינו.

@38 **התועלת** הראשון הוא במדות. והוא שראוי לאדם לתת שבח והודאה לשם יתעלה על שגמלהו מהטובות כי בזה מההישרה אל ההאמנה בשם יתע' מה שלא יעלם ולזה ספרה התור השמשה ובני ישראל שרו השירה הזאת ליי' לתת לו תודה על מה שגמלם מהטוב:
@38 **התועלת** השני הוא בדעות. והוא להודיע שמעלת השם יתע' עצומה מאד עד שלא יפול יחס בינו ובין הדברים אשר אצלנו ולזה ראוי כשנרצה לספר שבחי השם יתעלה שנדבר בדרך השיר וההמשל כי גבהה מדרגתו מאד עצמה מספר ולזה אמר אשירה ליי' כי גאה גאה:
@38 **התועלת** הג' הוא דעות. והוא להודיע כי הרע אשר יפול בנמצאות על צד ההכרח ישמר ה' ממנו הדבקים בו וזהו מה שאמר עזי וזמרת יה ויהי לי לישועה וזה כי הטוב הוא המכוון מעצמו מהש' יתע' והרע שיגיע במקרה מהטוב המסודר ממנו התחכם השם יתע' להציל ממנו האנשים הטובים כשידבקו בו על צד ההשגחה הפרטית ובזה האופן הציל השם יתע' ישראל מיד מצרים כי לפי מה שיתחייב מהגרמים השמימיים לא הגיע הקץ עדין אל שיצאו מעני מצרים כמו שביארנו במה שקדם ולזה גם כן אמר זה אלי ואנוהו ר"ל שאינני תחת סדור ממשלת הכוכבים אבל השם יתע' הוא משגיח בי ומנהיג אותי:
@38 **התועלת** הד' הוא בדעות. והוא להודיע שכבר יגיעו בכאן רעות לרעים על צד ההשגחה בטובים ואע"פ שאין מדרך השם יתע' שיבואו ממנו רעות אבל יבואו ממנו מהצד אשר הם טובות ולזה אמר שהשם יתע' וימינו תרעיץ אויב ושהוא יהרוס קמיו ברוב גאונו כמו שביארנו:
@38 **התועלת** הה' הוא בדעות. והוא להודיע יושר ה' שכבר יביא השם יתע' על האנשים מדה כנגד מדה וזו כי פרעה חשב לכלות ישראל עד בלי השאיר להם שריד כמו שספר אמר אויב ארדוף אשיג והשם יתע' סבב שהיה הענין בהפך כי מישראל לא נפקד איש ומפרעה וחילו לא נשאר אחד ועוד כי הוא רצה להשליך כל הזכרים הילודים לישראל היאורה כדי שיכלה ישראל והנפך זה כי הוא וחילו טבעו בים סוף:
@38 **התועלת** הו' הוא בדעות. והוא להודיע שאין יחס בינו ית' ובין שאר נבדלים ולזה אמר מי כמוך באלים יי' וכבר בארנו זה במה שאין ספק בו בחמישי מספר מלחמו' יי':
@38 **התועלת** הז' הוא להודיע שענין קריעת ים סוף היה בו תועלת להנחיל את הארץ לישר' מצד אחד זולת מה שנמשך ממנו להביא ישר' להאמין ביי' ומשה עבדו שהי' עשר גדול להביא ישר' לגבול מהשלמו' שיהיו ראוי' לירושת הארץ כמו שאמר נהלת בעזך אל נוה קדשך וזה הצד האחר הוא מה שהפיל מהאימה והפחד על האומו' ההם כששמעו שהוביש יי' את מי ים סוף מפניהם כמו שאמר אז נבהלו אלופי אדום אילי מואב:
@38 **התועלת** הח' הוא להודיע. שלא הי עקר הכונה במה שיעד השם יתעלה הארץ לישראל רבוי הפירות הנמצאים שם אבל היתצה הכונה בזה בעבור המצא שם השפע האלהי יותר ממה שימצא בשאר המקומות ולזה לא זכר משה מענין ירושת הארץ בזאת השירה כי אם הר המוריה. אמר תביאמו ותטעמו בהר נחלתך. ובאר שהוא מקום שידבק בו השפע האלהי ואלו היתה הכונה הראשונה בירושת הארץ רבוי הפירות היה זוכר גם כן שאר המקומות לא הר המוריה לבד אלא שעם כל זה תמצא שכבר היה רבוי הפירות נמצא בארץ ישראל כמו שזכרה התורה והיה זה התועלת מגיע מירושת הארץ על הכונה השנית עם מי שהוא עוזר להמשיך ליושבי' בה השפע האלהי כי לא יתכן שישתדל האדם בהשלמת נפשו בשלם שבפנים עם היותו חסר לחם ושמלה ושאר הענינים ההכרחיים לעמידת גופו:
@38 **התועלת** הט' הוא להודיע שזאת האמונה השלמה שהתפשטה בישראל או תשאר נצחית בדרך שיתפרסם תמיד מלכות השם יתע' ושולטנותו על הנמצאות לעשות מהם בהפצו וזה מה שאמר יי' ימלוך לעולם ועד:
@38 **התועלת** הי' הוא להודיע שאין מן הראוי שיכנסו אלו הנשים לספר שבחי השם יתעלה בכמו אלו העמוקות לחסרון דעתן. ולזה לא זכר בשירת הנשים כי אם מלות מועטות. ואולם בני ישראל שרו כל השירה הנפלאה הזאת. ולזאת הסבה בעינה לא חייבה התורה הנשים בתלמוד תורה ובשאר המצות הנוהגות מנהגה אמרו ז"ל כל המלמד את בתו תורה כאלו מלמדתה תפלות:
@59 והנה שאר דברי זה הספור מבוארים עם מה שקדם מהדברים. ואולם התועלות המגיעות ממנו הם ששה:
@59 **התועלת** הא' הוא להודיע רבוי הנפאלות שחדש השם יתעלה לישראל כדי שיאמינו בו ויהיו נכוני' לקבל התורה השלמה המישרת אל כל השלמיות עם מה שהיה מהקושי להעתיק ישראל אל זאת האמונה האמתית מצד מה שנשקעו בו מרעו' המצרים ומנהגיהם עד שכבר היו בועטי' תמיד בשם יתעלה ובמשה ניביאו והיה קשה להם הוציא אותם ממצרי' כו שנזכר בזה הספור פעמים רבות וזה היה כולו לחוזק השגחתו באבות כדי שישובו ישראל באופן מהשלמות שיהיו ראוים לירושת הארץ אשר בא ייעוד הש' יתע' לאבות לתת אותה לזרעם:
@59 **התועלת** הב' הוא בדעות. והוא להודיע שהשם יתעלה יציל הדבקים בו ההולכים בדרכיו מהרעות הנכונות לבא עליהם כמו שאמר והיה אם שמוע וגו'. כי אני יי' רופאך:
@59 **התועלת** הג' הוא להודיע איך התחכם השם יתעלה תכלית ההתחכמות שיאמינו ישראל במצות שבת כדי שיוכנו יותר לקבול התורה עם שמצות שבת היא פנה תורתינו תוריית עצומה כי היא מורה על חדוש העולם אשר הוא פנת תורתנו ולזה סבב השם יתעלה שיכירו ישראל גודל מעלת יום שבת באמצעות המן קודם שיגיד להם משה זאת המצוה:
@59 **התועלת** הד' הוא במדות. והוא שאין ראוי לאדם לסגף נפשו למנוע ממנו מזונו ההכרחיי ואין ראוי לו גם כן שיאכל יותר מן הראוי לעמידת גופו ולזה צוה השם יתעלה ישראל שילקטו עומר לגולגולת על צד האומר וסבב השם יתעלה על צד המופת שכאשר מדדו זה לא מצא כל אחד מהם כי אם השעור הראוי כי הכונה האלהית היתה שיהיה להם לחם חקם לא פחות ולא יותר להרגילם במדת ההסתפקות ולהרחיק מהם מה שיעשו שאר האומות לצער נפשם וידמו לעבוד השם יתעלה בזה האופן ולזאת הסבה גם כן צוה שלא יותיר איש ממנו עד בקר:
@59 **התועלת** הה' והוא במצות. והוא מה שנתבאר מזה הספור שההוצאה מרשות לרשות היא אסורה בשבת ולזה צוה שלא יצא איש ממקומו ללקט המן:
@59 **התועלת** הו' הוא להודיע מה שצוו להשאיר מלא העומר מן למשמרת להודיע לדורות הבאים אחריהם זה הפלא העצום כי בהאמנה בנפלאות היא מהגדולות שבפנות התוריות ולזה רצה השם יתעלה שתמשך זאת האמונה לדורות הבאים בהתפרסם להם זה הפלא העצום:

@117 והנה היתה דבורה שפטה אז את ישראל ואחשב כי בעת ששבו ישראל אל ה' היתה שופטת אותם והיא סבבה שישובו אל ה' כי הוא רחוק שיעשו ישראל הרע בעיני ה' ולא תוכיחם על זה דבורה והיא נביאה והנה יורה עוד על מה שאמרנו אמרו היא שפטה את ישראל בעת ההיא. וקראה אשת לפידות כי בעלה היה שמו ברק וברק ולפיד הם קרובים בענינ' או יהיה פי' אשת לפידו' ע"ד אשת חיל אשת מדני' ויהיה לפידים ולפידות ענין א' והרצון בו כי כבר הגיע עוצם מדרגת' בנבואה עד שהיו נראי' לפידי' במקו' שהיתה מגעת לה הנבואה כמו שספרה התורה במרע"ה:
@119 **אם** היה ברק בעלה ידמה שכבר פירשה ממנו מפני נבואת' ולזה הוצרכה לשלח לקרא לו במקום שהיה יושב והוא קדש נפתלי או היתה היא גם כן יושבת בקדש נפתלי אך למשפט יעלו אליה בני ישראל למקום ההוא שהיתה בו תמר ולזה יקראוהו תומר דבורה כי מנהגה היתה לשבת במשפט במקום ההוא, והנה אמרה דבורה לברק באמת צוה ה' אלהי ישראל שתעשה זה והוא שתמשוך בהר תבור לב ישראל באופן שתביא שם עשרת אלפי איש מבני נפתלי ומבני זבולון וזה אמנם יהיה על צד ההסתה והפתוי בדברים שיאמר להם על צד שכבר יעד השם להם בנבואה שינצחו חיל סיסרא ויש להם לבטוח בזה בש"י כי אין מעצור לה' להושיע ברב או במעט והש"י יסבב שימשך אליך אל נחל קישון סיסרא ורכבו והמונו ויתנהו בידך, ואם יאמר אומר למה שלח השם לצוות ברק שימשוך מישראל י' אלפים איש אל הר תבור בדברי פתוי והסתה ואיך לא משכם הש"י שם כמו שמשך סיסרא ורכבו והמונו אל נחל קישון, נאמר לו כי הש"י לא ישתדל בעשיית המופתים כי אם לעת הצורך ולפי שהיה אפשר שימשכו ישראל בזה האופן לא היה רצון הש"י לחדש להם רצון שיבואו שם על דרך מופת:
@121 והנה היתה תשובת ברק שאם תלך עמו דבורה במלחמה ילך ואם לאו לא ילך כי חשב כי בזכותה תדבק יותר ההשגחה עם חיל ישראל הנלחמים עם סיסרא:
@122 וענתה דבורה שכבר תלך עמו באמת אבל לא יהיה לו להתפאר על הדרך אשר הוא הולך כשינצח סיסרא המונו ורכבו. כי ביד אשה ימכור ה' את סיסרא. ר"ל ביד דבורה כי אליה נתיחס זה הנס כמו שיראה בדבר השירה הנזכרת אחר זה ונתנבאה עם זה שסיסרא יפול ביד אשה והיא יעל כמו שנתבאר בזה הספור:
@124 **והנה** זכר שחבר הקיני היה נפרד מקין מבני חובב חתן משה שספר למעלה שישבו את יהודה במדבר יהודה ונטה אהלו עד אילון בצעננים אשר את קדש ויורה פועל יעל שמנהג חבר הקיני היה כמנהג שאר בני חובב להתנהג בדת ישראל ולזה השתדלה יעל להרוג סיסרא ואמנם היה שלום בין חבר הקיני ובין סיסרא עם היות המלחמה בין סיסרא ובין ישראל כי אולי חבר הקיני נתן צוארו תחת עול יבין מלך כנען או היתה אהבה ביניהם לסבה אחר':
@125 והנה הוגד לסיסרא כי עלה ברק בן אבינועם הר תבור והזעיק סיסרא את כל רכבו ואת כל העם אשר אתו מחרשת הגוים אל נחל קישון והנה אמרו כי עלה ברק הוא לאות כי דבורה היתה אשת ברק כי אם לא היה הענין כן היה ראוי שיאמר כי עלתה דבורה וחילה כי היא היתה המנהגת את ישראל וזה כי הראש ראוי שיזכר בזה ואמנם מפני שהיה ברק בעלה יחס הראשיות לו:
@127 וצותה דבורה לברק שיקום להלחם עם סיסרא וחילו כי הש"י יצא לפניו להלחם בהם והנה נפלו כלם ביד ברק וחילו זולת סיסרא שחשב להמלט נפשו באהל יעל לפי שכבר היה שלום ביניהם ויעל הראת' עצמה חפצה להצילו וכסתה אותו בשמיכה בתוך אהלה שלא יראוהו שם והנה שמיכה הוא קו"טה בלע"ז והנה שאל מים ונתנה לו חלב להרדימו עם מה שעזר להרדימו היותו עיף ויגע כדי שתוכל להמיתו בהיותו נרדם והנה לקחה יעל את יתד האהל שהיה מברזל לפי מה שאחשוב:
@134 ותשם את המקבת בידה. הוא כלי ברזל שמכין בו האבנים ופוסלין אותן ושמה היתד כנגד רקתו והכתה במקבת על היתד עד שנתקע היתד ברקתו ונפלה בארץ ונתקעה בה והנה סיסרא היה נרדם וכבר היה עיף קודם זה ולזה לא הרגיש בזה הפועל:
@135 **והנה** ברק היה רודף את סיסרא כשלא מצאהו בדרכו שרדף עד חרושת הגוים ועל' על דעתו כי כבר היה נחבא באחד מהמקומות והודיעה אותו יעל כי הוא מת בביתה ונתבאר לברק כי יעל המיתתהו כי ראה היתד ברקתו:
@137 ובסוף הענין הכריתו בני ישראל בימי דבורה את יבין מלך כנען ועל זה הנס שעשה הש"י לישראל על יד דבורה שרה היא וברק זאת השירה שזכר ואין הרצון בזה שיהיה ברק עוזר לה בעשיית שירה כי היא לבדה עשתה אותה והנה נזכר עמה ברק כזכר אז ישיר משה וגו':
@139 בפרוע פרעות. הוא מענין השבתה וביטול והרצון בזה כי עם היות ישראל מושבתים ומבוטלים מהגבורה מפני לחץ סיסרא ויבין והיו מפני זה בתכלית החולשה ראוי מפני זה לברך הש"י כשהתנדבו עם ישראל לעלות עליהם למלחמה עם ראותם חולשתם וגבורת סיסרא וחילו כי זה היה נפלא מאד:
@140 **שמעו מלכים.** ר"ל מלכי האומות כדי שיראו מלהרע לישראל: **אנכי לה'.** ר"ל כי לא עם אחר ולזה נאה לי לשיר ולזמר לה' אלהי ישראל כי הפליא חסדו לי:
@141 **ה', בצאתך משעיר.** ובלכת צעדיך משדה אדום ארץ רעשה ואמר על צד המשל כאילו השמים והעבים נתכו והיו למים והנה אמר זה למשל על מלחמת סיחון ועוג על שהיו רחוקים וגבוהים מאד שהיתה אחר צאת ישראל משעיר שהוא שר אדום כמו שנזכר זה בתורה ורמז עוד בזה על שאר המלחמות שהיו אחר זה ובכמו זה האופן מהמשל דברו הנביאים במקומות רבים:
@142 **הרים נזלו.** יתכן שרמז בזה על מתן תורה ואמר שגם ההרים בעצמם נזלו ונתכו וחרדו מפני ה' וזה היה ביום מ"ת שנתחדש המופת מן ההר ההוא זה הר סיני אז נזל מפני ה' אלהי ישראל ובזה נשלם בקיצור זכירת החסדים שעשה השם לישראל במלחמות האומות ולחם בם מלחמות תנופה כענין מ"ת והנפלאות שחדש שם שהיו סבה שיאמינו ישראל בו ויקבלו מצותיו:
@143 **ואחר** זה שבה דבורה להזכיר בזאת השירה הענין שבו היה זה הנס והתחילה ואמרה כי בימי שמגר בן ענת אף על פי שהושיע את ישראל תשועה מה כמו שקדם חדלו ארחות ר"ל שהולכי דרכים חדלו מהלוך בהם מפחד האויב ואם היה שילכו בדרך ילכו ארחות עקלקלות ויטו מדרך הישר כדי שלא ימצאם האויב:
@144 חדלו פרזון. ר"ל שערי הפרזות חדלו מהיות בהן יושב מפחד אויב ולא נשארו ישראל אז כי אם בערים המוקפים חומה וכן הענין בימי יעל ידמה מזה שיעל נמנית בכלל המושיעים קודם זה המעשה שעשתה בהמיתת סיסרא והיה זמן שמגר בן ענת וזמן יעל נכללים בכ' שנה שלחץ סיסרא בחזקה או אמר זה על זה המעשה שעשת מהמיתת סיסרא להגיד שלא היה רושם מוחש במה שעשתה לישועה הגדולה שבאה מזה וזה מבואר מאד ואפילו הראשון הוא יותר נכון: **עד שקמתי דבורה שקמתי.** אני הייתי אם ומנהגת ישראל:
@145 **יבחר אלהים חדשים.** פי' בו כי בעת שבחר ישראל בע"ג שהם אלהים חדשים אז היתה להם המלחמה בשערים ולא יכלו לצאת לחוץ ואפשר לפרש כי הש"י בחר דברים חדשים להשלים זה הנס והוא שכבר משך לב סיסרא וחילו להלחם עם ברק בשערי ישראל במקום שהיה ראוי ליפול שם לפי מה שסבב הש"י אשר עמקו מחשבותיו והנה באמת לא נצחו ישראל זאת המלחמה בכחם ועוצם ידם כי לא היו להם כלי זין כי אם לאנשים מועטים עד שבכל ישראל לא היה מגן ורומח בארבעים אלף ולזה הוא מבואר כי בעשרת אלפים איש שעלו מבני נפתלי ומבני זבולן לא היו כלי זיין כי אם לאנשים מועטים:
@146 **לבי לחוקקי ישראל.** ר"ל החכמים והסופרים המתנדבים בעם להשלימם וללמדם תורה ומצות הנה ראוי לכם לברך השם יתעלה על התשועה הגדולה שהושיע את ישראל כי לא היו יכולין ללמוד תורה וללמד מלחץ אויב או אמר זה על בני נפתלי ועל כני זבולן שירדו מהם מחוקקים לעזור לדבורה בזאת המלחמה כמו שיבא אחר זה:
@147 **רוכבי אתונות וגו'.** הסוחרים הנכבדים רוכבי אתונות לבנות שהיו יושבים על דרך מדין ומתעכבים שם ולא יוכלו להשלים דרכם הישר מפני פחד אויב ויטו דרכם ללכת על דרך אחר והוא דרך שיחו כמו שאמר במה שקדם והולכי נתיבות ילכו ארחות עקלקלות:
@148 **מקול מחצצים.** וכל זה הפחד היה להם מקול האויבים מורי החצים שהיו בין המעינות שהיו שואבין מהן המים להצר להם לישראל שלא יוכלו לשאוב משם והיה זה המקום בדרך הישר שהיו רגילים ללכת בו הסוחרים ומפני זה היו הולכים ארחות עקלקלות והנה במקום ההוא שלא היו יכולין לבא שם שם יתנו ויגידו צדקות ה' שהכרית את אויביהם המצירים להם שם ויתנו ג"כ צדקות פרזונו בישראל עתה שיוכלו בני ישראל לשבת בערי הפרזות אשר הניחום ועזבום מפחד אויב: **אז ירדו לשערים עם ה'.** ר"ל שישבו בכל שעריהם לפי ששבו לערי הפרזות לשבת, או יהיה הרצון בזה אז ירדו עם ה' לשערים ללמוד תורה מה שלא היו יכולין בו קודם זה כי הדרך היה סגור לפניהם מפני האויבים וכובד השעבוד ג"כ היה מונעם מזה:
@149 **עורי עורי דבורה.** יחס לדבורה דברי השיר ולברק יחס שבית השבי שהוא פועל המלחמה:
@150 **אז ירד.** אז ישים השם רודה מה ששרד ונשאר מישראל על אדירים וחזקים והם עם יבין מלך כנען כ"ש ויכנע אלהים ביום ההוא את יבין מלך כנען לפני בני ישראל ה' שם רודה ומושל לי בגבורים ר"ל ששם ישראל רודה ומושל על הגבורים ההם והם עם יבין מלך כנען:
@151 **והנה** התחילה דבורה לספר ענין השבטים במלחמות והתחילה מן אפרים כי על ידו נעשית המלחמה הראשונה ואמ' מן אפרים שרשם מי שהיה שרשם והוא יהושע שהיה נשיא עליהם והיה היותר נכבד שבשבט נלחם בעמלק כמו שנזכר בתורה ויחלוש יהושע וגו'. אחריך. תביא אתה שתהיה משבט בנימן בעממיך להלחם עם עמלק והוא שאול ומן מכיר בני מנשה שהיה חלק לעבר הירדן ירדו החכמים עם דבורה למלחמה וכן הענין מזבולן:
@152 **ושרי ביששכר.** והשרים שהם ביששכר ג"כ ירדו עם דבורה ושבט יששכר בכללו וכן שמע לעצת דבורה ברק עד שבעמק שולח ברגליו בעצת דבורה כמו שאמר ויעל ברגליו עשרת אלפי איש ואולם כפלגות ראובן גדולים חקקי לב:
@153 **והנה** תמה עליו למה ישבת בין המשפתים במקומך ולא התעוררת בזאת המלחמה אבל היית יושב ובוטח והיית שומע שריקות עדרי ישראל על ידי האויבים והיית שוכן במקומך ולא חששת לזה הנה לפלגות ראובן גדולים חקרי לב על ששקדו עליהם ולא נתנו לב לצאת משם:
@154 גלעד בעבר הירדן שכן. וא"ת כי מנעך מזה הירדן הלא גלעד ג"כ שוכן בעבד הירדן ועם כל זה בא לעזרת ה' בגבורים כמו שקדם והנני תמה על דן למה יגור אניות הנה נחלתו לא היתה מעבר הירדן ולא די שלא בא לעזרת ה' אבל ברח והניח עמו והלך עם קניניו בעבר הירדן באניות כמו שתרגם יונתן הנה אשר יש לו התנצלות אם לא בא לעזרת ה' כי הוא יושב על הספר ולזה היה ראוי לשמור ארצו ולשכון על המקומו' הפרוצים בארצו שלא יבאו שם האויבים:
@155 **ואמנם** זבולן ונפתלי ראוי שישובחו והוא כי זבולון הוא עם שחרף נפשו למות מרוב קנאתו להנקם מהאויב ר"ל שמסר עצמו לסכנה, וכן נפתלי ג"כ כי מבני נפתלי ומבני זבולן היו החיל אשר עלו עם ברק על הר תבור שהיו על מרומי שדה כי הם ראו חיל עם סיסרא ועם זה מסרו עצמם לסכנה לעלות עליהם למלחמה מרוב בטחונם בשם ית':
@156 באו מלכים נלחמו. ידמה שמלכים דבים מממלכות הגוים ממשפחות כנען ירדו עם סיסר' להלחם עם ישראל ונלחמו אז מלכי כנען בתענך ועל מי מגדו והם המקומות שהיו חושבים לכבשם בקלות וכל כך היו חפצים להלחם בישראל שלא לקחו בצע כסף על זה מיבין מלך כנען כמנהג מי שאינו תחת המלך שאם ירצה המלך להביאו למלחמתו יתן לו שכר:
@157 **מן שמים נלחמו.** אמר זה להורות כי לא בחרבם נצחו לסיסרא אך מאת ה' ית' בא להם זה הניצוח והוא ית' שם הכוכבים ממסילותם נלחמים עם סיסרא בהשפיע באמצעותם מה שישלם בו ניצוח סיסרא וחילו:
@158 **נחל קישון גרפם.** ידמה שכבר גברו אז על דרך מופת מי נחל קישון שהיו בו מים מעטים וכשהיו עוברים בו סיסרא וחילו גברו המים והסירום כמו שתסיר המכבדת אשר יכבדו בה הבית מה שעל הארץ מן העפר וזולתו ובזה האופן טבעו רוב חיל סיסרא ונפל פחדם אל הנשארים ועם זה הענין הנה בנחל המים הקדומים שהיו בנחל קישון: **תדרכי נפשי עוז.** ר"ל שלא גברו המים לישראל בעברם בדרך שיניעום ויסירום ממקומם אבל היו דורכין שם בעוז ותוקף וזה היה פלא גדול דומה באופן מה לפלא שהיה לישראל על ים סוף:
@159 **אז הלמו.** אז נהלמו ונשברו עקבי סוס סיסרא שלא נשאר להם כח מחוזק מרוצתם והכותם בהם בארץ כשהנהיגום גבורי סיסרא ולא נשאר להם כח לנוס ואפשר שיהיה הרצון בזה כי אז בנחל קישון מרוב המים שגברו שם היו עקבות סוסיהם כאילו נשברו ולא יכלו לדהר אבל נגבו המים רגליהם:
@160 **אורו מרוז.** שהיתה עיר גדולה קרובה למקום המלחמה: **אמר מלאך ה'.** זאת הנבואה לדבורה שעיר מרוז תהיה ארורה ר"ל יושביה כי לא באו לעזרת ה' עם היותם קרובים:
@161 **תבורך מנשים.** אמנם יעל תהיה ברוכה כי עזרה להם בהריגת סיסרא ויותר מנשים שהן באהל תבורך או ירצה בזה שהיא תבורך מנשים שהן באהל ללמד תורה כמו דבורה ויהיה הרצון בזה כי קללת מרוז אמר מלאך ה' ואולם ברכת יעל אמרה דכורה על צד התפלה והברכה:
@162 **והנה** ספרה על מה ברכה יעל וזה כי היא עשתה מעשיה בחכמה ובגבורה לעזור ישראל וזה שכאשר שאל סיסרא מים לשתות נתנה חלב לשכרו והקריבה לו חמאה בכלי גדול לשתות והרצון בחמאה חלב שמן שלא הוסרה ממנו החמאה כי הוא משכר יותר, והנה נכפל הלשון בזה, ומה שספר תחלה כי מנאד החלב השקתהו היה בזה האופן ר"ל שהוציאה ממנו בספל גדול אשר ישתו בו הגבורים:
@163 ידה ליתד תשלחנה. והנה כחתיה המנהיגים הגוף תשלחנ' ידה השמאלית ליתד ושלחו ימינה למה שהולמים ומכין בו העמלים במלאכות רבות העמל והכתה סיסרא בראשו עד שהפסידה ופרדה החבור אשר בו והכתה ביתד ועברה היתד רקתו או כרתה רקתו:
@164 **בין רגליה כרע נפל.** ר"ל כי בחכמתה סבבה שנפל ונרדם לפניה: **ובאשר כרע שם נפל שדוד.** ר"ל כי תכף שנפל שדדתהו והמיתתהו יעל:
@165 **הנה** אם סיסרא נשקפה בעד החלון והילילה בדמיון תרועה והיתה אומרת מה הסבה שיהיה בושש רכב סיסרא לבוא:
@166 והנה החכמות שבשרותיה היו עונות אותה וגם היא בעצמה היתה משיבה לדבריה ואומרת מה שאומרת החכמות ההן והוא כי סבת איחורו הוא שאם ימצאו שלל שיחלקוהו:
@167 רחם רחמתים. ולהיות פרוצים בעריות הקדימו בספור שלל העריות אולי השיג כל אחד מהן נערה אחת או שתים ולסיסרא ג"כ יתנו שלל בגדי הצבעונים הנכבדים שלל בגדי צבעונים שהם מרוקמים ובגדי צבע רקומים משני עבריהם ויחלקם סיסרא לצוארי בעלי השלל והם אנשי החיל הבאים עמו:
@168 **והתפללה** דבורה ואמרה כן יאבדו כל אויבי ה' כמו שאבד סיסרא ואוהבי השם יתעלה יהיו כצאת השמש בגבורתו שאורו הולך ומתחזק עד נכון היום, והרצון באמרו בגבורתו בראש תקופת תמוז כי אז יראה אורו יותר חזק והחום המגיע ממנו הוא יותר חזק ויהיה הולך ומתחזק עד חצי היום, ושקטה הארץ עד שלמות ארבעים שנה מעת התחלת השעבוד ולזה יהיה זמן ההשקט עשרים שנה. ואולם התועלות המגיעות מזה הספור הם אלו. הראשון הוא להודיע כי השם יתעלה לא יעשה המופתים רק לעת הצורך ולזה צוה ברק למשוך בהר תבור עשרת אלפי איש מבני נפתלי ומבני זבולון ולא משכם שם השם יתברך כמו שמשך אל נחל קישון סיסרא ורכבו והמונו וזה כי משיכת בני ישראל בהר תבור היה אפשר שישלם בזולת עשיית המופת וכבר ביארנו הסיבה בזה בספר מ"י. השני הוא להודיע כי כשיעשה הש"י המופתים יסבב עליהם הסבות אשר עמם יהיה יותר מעט מהזרות במופת ההוא אצל הטבע ולזה התחכם הש"י להביא בני ישראל בהר תבור והעתיק שם סיסרא ועמו אל נחל קישון לרדוף אחרי ברק ועמו וסבב עם זה שרבו מי הנחל עד שטבעו בו רבים מבני החיל ונתקבצו בזה סבות רבות אל שינצחום ברק ועמו, הא' היא הבהלה שהבהילום מי הנחל והב' כי ברק ועמו היו יורדים אליה' ולזה היו עליונים וזה ממה שיוסיף להם חוזק על סיסרא ועמו וידמה שנתחברה שם סבה שלישית והיא שכבר היה אור השמש נכח פני סיסרא ועמו והיה משים סנוירים בעיניהם ולזה אמרה דבורה כי הכוכבים ממסלותם נלחמו עם סיסרא. השלישי הוא להודיע אמתת הנבואה אף על פי שהיתה ע"י אשה כי לא נפל דבר ממה שיעדה דבורה בזה הספור, והנה לפרסום אמתת הנבואה אז נסכמו ישראל ללכת במתי מעט ובכלי מלחמה מעטים להלחם עם סיסרא ורכבו והמונו עם תכלית כחו וגבורתו ורבוי כלי המלחמה אשר להם. הרביעי הוא להודיע כי בתחבולות ראוי שיתנהג האדם להגיע אל תכלי' כוונתו ולזה ספר כי יעל מפני רצותה שיפול סיסרא בידה הראת לו כי היא חפצה מאד בהצלתו וכסתה אותו כדי שלא יראוהו שם העוברים והשבים וסבבה עם זה ששכרה אותו ונרדם עם המופת והיה נקל לה להורגו. החמישי הוא להודיע כי ביום טובה ראוי להיות בטוב ולזה ראוי למצליח בעת אשר יש לאל ידו שיסבב שתגיע לו ההצלחה ביותר שלם שבפנים ולא יקצר מזה הלא תראה כי ברק אע"פ שראה שנפל כל מחנה סיסרא לפי חרב לא נשאר עד אחד השתדל בתכלית מה שאפשר על הריגת סיסרא פן ישוב אל אדוניו וישיב להרע לישראל. הששי הוא להודיע לתת תודה לש"י על מה שגמל מהטובות כי עם שזה כבר ראו הנה בו תועלת להביא האנשים להאמין שכל הטובות באו מאתו ולזה שרה דבורה השירה הזאת ונתנה תודה לשם יתעלה כעל כל אשר גמלנו. השביעי הוא להודיע שראוי לכל אדם שיאמין ביעודי הנבואה ולזה נתגנו אשר לא באו לעזרת ה' בגבורים כנגד מחנה סיסרא ונתקללו יושבי מרוז מאת השם יתברך. השמיני הוא לפרסם גנות האומות ההם והיותם פרוצים בעריות ולזה הקדימה אם סיסרא בספור הצלחת סיסרא רחם רחמתים לראש גבר וכבר פרסמה התורה ג"כ ממנהגיהם הפחותים עוד ספר ששבו בני ישראל לעשות הרע בעיני ה' אחר מות דבורה ולזה נתנם השם ביד מדין ז' שנים ותקפה יד מדין מאד על ישראל עד שהוצרכו לעשות להם בהרים מנהרות והן מערות שיש בהן כמו חלונות תכנס מהן אורה במערה, ואפשר שהרצון יהיה במנהרות אבוקות בעלות אור גדול והיה זה כן כי כשהיו רואין ההרים שבאו בני מדין היו עושין באבוקות ההן סימן שירגישו בו ישראל ויתחבאו הם ויסתירו מקניהם וקנינם עד שבזה הדרך היתה מגעת בקלות ההודעה הזאת לישראל בעשותם הסימן הזה להם מהר אל הר והיה אפשר שיצילו מאויביהם דברים רבים ועכ"ז עשו מערו' להתחבא שם בקלות ומצדות שהם בניינים חזקים להמלט שם מאויביהם לא שישבו תמיד במערות ובמצודות כי היה בלתי אפשר שישלם להם חיותם בזה האופן כי לא יזרעו ולא יאספו תבואה, ואחר זה ביאר מה הכריחם לעשות המנהגות והמערות והמצדות והוא מה שהיו משחיתים בני מדין תבואותיהם ומקניהם, ויהי כי צר להם מאד מפני מדין צעקו אל ה' ושבו אליו שיושיעם מידם, והנה שלח הש"י נביאו אז לבני ישראל והודיעם כי עונותיהם הטו שיפלו ביד מדין כי הם סרו מאחרי ה' ועבדו אלהים אחרים אלהי האמורי אשר בארצם עם רוב הטובות שחנן הש"י אותם וידמה שזה הנביא היה פנחס כמו שזכרו רז"ל בפנחס בימי דוד שהגיד הכתוב כי לפנים ה' עמו והנה חיה זמן ארוך מאד ולזה אמרו כי פנחס הוא אליהו כי כבר התבאר שאליהו ג"כ חיה שנים רבות וכבר יעד מלאכי שהש"י יביאהו בימי הגאולה אמר הנה אנכי שולח לכם את אליה הנביא וגו' ואין לאומר שיאמר שכבר מת אליהו קודם שהתנבא אלישע כמו שאמר כי היום אדוניך לוקח מאתך וזה שכבר מצאנו שהגיע מכתב מאליהו אחר זה כמו שנבאר שם בע"ה בספר דברי הימים ובספר מלכים:
